window.SKD_QUESTIONS = [{"id":1,"section":"TWK","stem":"Perkembangan industri fashion global membuat banyak generasi muda lebih tertarik menggunakan produk dari merek internasional. Di sisi lain, sejumlah desainer lokal mulai mengembangkan pakaian modern dengan mengadaptasi motif kain tradisional Indonesia. Namun, sebagian masyarakat menilai bahwa penggunaan motif tradisional dalam desain modern dapat mengurangi nilai keaslian budaya. Sikap yang paling mencerminkan nasionalisme dalam menghadapi situasi tersebut adalah","options":{"A":"Mendukung penggunaan motif tradisional dalam produk fashion modern selama karakteristik dan nilai budaya yang terkandung di dalamnya tetap dipertahankan.","B":"Mengutamakan penggunaan pakaian tradisional dalam kegiatan tertentu sebagai bentuk penghormatan terhadap warisan budaya bangsa.","C":"Mendorong desainer lokal untuk mengembangkan produk fashion yang mengikuti perkembangan tren internasional agar mampu bersaing di pasar global.","D":"Mengapresiasi inovasi fashion berbasis budaya lokal sekaligus mendorong pengenalan asal-usul dan makna budaya yang digunakan kepada masyarakat luas.","E":"Mengembangkan industri fashion nasional melalui kolaborasi dengan desainer internasional agar produk Indonesia semakin dikenal di pasar dunia."}},{"id":2,"section":"TWK","stem":"Seorang kreator konten Indonesia memiliki jutaan pengikut di media sosial. Ia menyadari bahwa konten yang membahas budaya populer luar negeri cenderung memperoleh jumlah penonton lebih tinggi dibandingkan konten tentang sejarah dan kebudayaan Indonesia. Beberapa pengikutnya menyarankan agar ia lebih banyak membuat konten internasional supaya akunnya semakin berkembang. Namun, iajuga ingin berkontribusi dalam memperkuat rasa cinta tanah air di kalangan generasi muda. Langkah yang paling mencerminkan nasionalisme adalah ....","options":{"A":"Memperbanyak konten budaya Indonesia dengan menggunakan gaya penyampaian yang menarik agar mampu bersaing dengan konten internasional.","B":"Mengembangkan konten yang membandingkan keunggulan budaya Indonesia dengan budaya negara lain untuk meningkatkan kebanggaan generasi muda.","C":"Mengombinasikan konten budaya populer internasional dengan informasi mengenai budaya Indonesia agar pengikut tetap tertarik mengenal identitas bangsanya.","D":"Menggunakan popularitasnya untuk mengajak kreator lain memprioritaskan konten budaya nasional sebagai bentuk tanggung jawab terhadap pelestarian budaya.","E":"Mengemas konten budaya dan sejarah Indonesia melalui pendekatan kreatif yang sesuai dengan minat generasi muda, disertai informasi yang akurat untuk meningkatkan pemahaman dan kebanggaan terhadap bangsa."}},{"id":3,"section":"TWK","stem":"Sebuah universitas di Indonesia menyelenggarakan seminar internasional yang menghadirkan akademisi dari berbagai negara. Sebagian panitia mengusulkan agar seluruh kegiatan menggunakan bahasa Inggris untuk meningkatkan citra internasional kampus. Namun, mayoritas peserta merupakan mahasiswa Indonesia dengan tingkat kemampuan bahasa Inggris yang beragam. Sebagai ketua panitia, keputusan yang paling mencerminkan nasionalisme adalah ....","options":{"A":"Menggunakan bahasa Indonesia sebagai bahasa utama kegiatan dengan menyediakan fasilitas penerjemahan bagi pembicara dan peserta internasional.","B":"Menerapkan komunikasi dwibahasa secara bergantian agar peserta Indonesia dan internasional memperoleh kesempatan yang sama untuk memahami materi.","C":"Menggunakan bahasa Inggris dalam sesi pemaparan ilmiah dan bahasa Indonesia dalam sesi diskusi agar kegiatan tetap memiliki standar internasional.","D":"Memberikan kebebasan kepada setiap pembicara menggunakan bahasa yang paling dikuasai dengan menyediakan ringkasan materi dalam bahasa Indonesia.","E":"Menyesuaikan penggunaan bahasa berdasarkan kebutuhan setiap sesi dengan tetap memberikan ruang bagi bahasa Indonesia sebagai identitas nasional."}},{"id":4,"section":"TWK","stem":"Sebuah sekolah akan menyelenggarakan festival budaya untuk memperingati Hari Sumpah Pemuda. Setiap kelas diminta menampilkan kebudayaan dari daerah yang berbeda. Namun, beberapa siswa mengusulkan agar sekolah hanya menampilkan budaya yang paling populer supaya acara lebih menarik dan mudah dipersiapkan. Sebagai ketua panitia, tindakan yang paling mencerminkan nilai nasionalisme adalah....","options":{"A":"Mengutamakan penampilan budaya yang dikenal luas sambil menyisipkan informasi mengenai kebudayaan daerah lain agar kegiatan tetap menarik dan edukatif.","B":"Memberikan kesempatan kepada seluruh kelas untuk memilih budaya daerah yang ingin ditampilkan sesuai kemampuan dan kreativitas masing-masing.","C":"Menyusun pertunjukan yang mewakili keberagaman budaya Indonesia serta memberikan pemahaman bahwa setiap budaya daerah memiliki kedudukan penting dalam identitas bangsa.","D":"Mengembangkan festival budaya dengan menggabungkan pertunjukan tradisional dan modern agar siswa lebih antusias mengenal kebudayaan Indonesia.","E":"Mengajak seluruh siswa berpartisipasi dalam kegiatan budaya melalui pertunjukan, pameran, dan diskusi untuk memperkuat rasa kebersamaan antarkelas."}},{"id":5,"section":"TWK","stem":"Sekelompok mahasiswa Indonesia mengikuti program pertukaran budaya di luar negeri. Dalam kegiatan tersebut, setiap negara diminta memperkenalkan identitas nasionalnya melalui pertunjukan dan presentasi. Beberapa mahasiswa mengusulkan untuk menampilkan budaya dari satu daerah yang sudah terkenal secara internasional agar penonton lebih mudah mengenali Indonesia. Namun, mahasiswa lainnya menganggap kesempatan tersebut sebaiknya digunakan untuk memperkenalkan keberagaman budaya Nusantara. Sikap yang paling mencerminkan nasionalisme adalah ....","options":{"A":"Menampilkan budaya daerah yang telah dikenal secara internasional sambil menjelaskan bahwa Indonesia masih memiliki banyak kebudayaan lain yang menarik untuk dipelajari.","B":"Menggabungkan beberapa pertunjukan budaya dari berbagai daerah dengan memperhatikan kualitas penampilan agar Indonesia memberikan kesan positif di hadapan peserta internasional.","C":"Memilih kebudayaan yang paling mencerminkan karakter masyarakat Indonesia berdasarkan kesepakatan seluruh anggota kelompok agar presentasi lebih terarah.","D":"Menampilkan beragam kebudayaan Indonesia melalui pendekatan kreatif dengan mengutamakan daya tarik pertunjukan dan kemudahan pemahaman penonton internasional.","E":"Memperkenalkan keberagaman budaya Nusantara sebagai bagian dari satu identitas nasional serta menjelaskan nilai persatuan yang menghubungkan masyarakat Indonesia di tengah perbedaan."}},{"id":6,"section":"TWK","stem":"Pada masa penjajahan Belanda, Ki Hadjar Dewantara mendirikan Perguruan Taman Siswa sebagai salah satu bentuk perjuangan melalui pendidikan. Lembaga tersebut tidak hanya memberikan pengetahuan kepada masyarakat, tetapi juga mengembangkan pendidikan yang berakar pada kebudayaan bangsa. Apabila dikaitkan dengan semangat nasionalisme, makna paling mendasar dari perjuangan tersebut adalah ....","options":{"A":"Membangun sistem pendidikan yang mampu mengembangkan kemampuan intelektual masyarakat dengan memanfaatkan kemajuan ilmu pengetahuan dari berbagai negara.","B":"Menjadikan pendidikan sebagai sarana membentuk manusia yang mandiri, memiliki kesadaran kebangsaan, dan mampu memajukan bangsanya tanpa kehilangan identitas budaya.","C":"Mengembangkan lembaga pendidikan yang memberikan kesempatan kepada masyarakat pribumi untuk memperoleh keterampilan dan meningkatkan kesejahteraan hidupnya.","D":"Menciptakan sistem pembelajaran yang memberikan kebebasan kepada peserta didik untuk mengembangkan potensi diri sesuai kemampuan dan kebutuhan masyarakat.","E":"Meningkatkan kualitas pendidikan masyarakat melalui penguatan pengetahuan, keterampilan, dan pembentukan karakter sebagai bekal menghadapi perubahan zaman."}},{"id":7,"section":"TWK","stem":"Seorang pegawai ditunjuk menjadi anggota tim seleksi penyedia barang untuk sebuah instansi. Ketika proses evaluasi berlangsung, ia mengetahui bahwa salah satu perusahaan peserta seleksi dimiliki oleh kerabat dekatnya. Perusahaan tersebut memiliki penawaran yang kompetitif dan berpotensi memenangkan seleksi. Meskipun tidak ada permintaan khusus dari kerabatnya, pegawai tersebut menyadari adanya potensi konflik kepentingan. Tindakan yang paling mencerminkan integritas adalah ....","options":{"A":"Tetap menjalankan tugas sebagai anggota tim seleksi dengan memastikan seluruh penilaian dilakukan berdasarkan kriteria yang telah ditetapkan secara objektif.","B":"Meminta anggota tim lainnya memberikan penilaian terhadap perusahaan kerabatnya agar keputusan yang dihasilkan lebih transparan dan dapat dipertanggungjawabkan.","C":"Mengungkapkan hubungan kekerabatan kepada pihak berwenang dan mengundurkan diri dari proses penilaian yang berpotensi menimbulkan konflik kepentingan sesuai mekanisme yang berlaku.","D":"Menyerahkan proses evaluasi teknis kepada anggota lain sambil tetap mengawasi jalannya seleksi untuk memastikan seluruh perusahaan memperoleh perlakuan yang adil.","E":"Menyampaikan potensi konflik kepentingan kepada ketua tim dan meminta keputusan dilakukan secara kolektif berdasarkan hasil penilaian seluruh anggota."}},{"id":8,"section":"TWK","stem":"Seorang mahasiswa menjadi ketua kelompok penelitian yang akan mengikuti kompetisi ilmiah tingkat nasional. Beberapa hari sebelum batas pengumpulan, ia menemukan kesalahan pengolahan data yang menyebabkan hasil penelitian terlihat lebih baik daripada kondisi sebenarnya. Jika kesalahan tersebut diperbaiki, kesimpulan penelitian kemungkinan berubah dan peluang kelompok memenangkan kompetisi menjadi lebih kecil. Anggota kelompok menyarankan agar mereka tetap mengumpulkan hasil yang ada karena seluruh proses penelitian telah dilakukan dengan sungguh-sungguh. Sikap yang paling mencerminkan integritas adalah ....","options":{"A":"Memeriksa kembali seluruh data yang terdampak, memperbaiki hasil penelitian secara jujur, dan menyampaikan kesimpulan sesuai temuan sebenarnya meskipun dapat memengaruhi peluang kemenangan.","B":"Mendiskusikan kesalahan dengan seluruh anggota kelompok untuk menentukan langkah perbaikan yang dapat mempertahankan kualitas penelitian tanpa mengabaikan kontribusi setiap anggota.","C":"Berkonsultasi dengan dosen pembimbing mengenai kesalahan pengolahan data agar kelompok memperoleh arahan yang tepat sebelum menentukan keputusan akhir.","D":"Menambahkan penjelasan mengenai keterbatasan pengolahan data dalam laporan penelitian agar pembaca dapat memahami kondisi yang memengaruhi hasil penelitian.","E":"Melakukan pengujian tambahan untuk memperoleh data pembanding sehingga kelompok dapat mengevaluasi kembali kesimpulan penelitian secara lebih komprehensif."}},{"id":9,"section":"TWK","stem":"Sebuah lembaga sosial memiliki data pribadi masyarakat penerima bantuan, termasuk alamat dan nomor telepon. Suatu hari, sebuah perusahaan menawarkan kerja sama untuk menyalurkan bantuan tambahan kepada keluarga yang membutuhkan. Perusahaan tersebut meminta daftar kontak penerima bantuan agar proses distribusi dapat dilakukan lebih cepat. Pengelola lembaga menyambut baik tawaran tersebut karena dapat memperluas manfaat program. Tindakan berikut yang paling TIDAK mencerminkan integritas adalah ....","options":{"A":"Mengembangkan mekanisme kerja sama yang memungkinkan bantuan disalurkan melalui lembaga sosial tanpa harus memberikan akses langsung terhadap data pribadi penerima.","B":"Memberikan daftar kontak terbatas kepada perusahaan yang dinilai tepercaya agar bantuan segera disalurkan, disertai permintaan agar informasi tersebut dijaga kerahasiaannya.","C":"Meminta persetujuan penerima bantuan sebelum membagikan data yang diperlukan, dengan memastikan informasi digunakan sesuai tujuan yang telah disampaikan.","D":"Menyampaikan informasi kebutuhan masyarakat dalam bentuk data agregat tanpa identitas pribadi agar perusahaan dapat menentukan bentuk bantuan yang sesuai.","E":"Mengajak perusahaan menyelenggarakan pendaftaran sukarela bagi masyarakat yang ingin menerima bantuan tambahan melalui mekanisme pengumpulan data yang transparan."}},{"id":10,"section":"TWK","stem":"Seorang bendahara organisasi mahasiswa bertanggung jawab mengelola dana kegiatan yang berasal dari bantuan sponsor. Setelah kegiatan selesai, ternyata terdapat sisa anggaran karena beberapa kebutuhan dapat dipenuhi dengan biaya lebih rendah daripada perkiraan. Ketua panitia mengusulkan agar seluruh dana tetap digunakan untuk mendukung program organisasi berikutnya. Namun, laporan pertanggungjawaban kepada sponsor harus segera diserahkan. Sikap berikut yang paling TIDAK mencerminkan integritas adalah ....","options":{"A":"Menyusun laporan berdasarkan pengeluaran sebenarnya dan mencantumkan sisa dana secara transparan agar sponsor mengetahui kondisi penggunaan anggaran.","B":"Mengusulkan kepada sponsor agar sisa dana dapat dialihkan untuk kegiatan organisasi berikutnya melalui persetujuan dan mekanisme yang sesuai.","C":"Mengadakan evaluasi anggaran bersama panitia untuk menentukan kebutuhan lanjutan yang masih relevan dengan tujuan bantuan sebelum mengajukan persetujuan penggunaan dana.","D":"Menyampaikan hasil efisiensi anggaran kepada sponsor sebagai bentuk keberhasilan pengelolaan dana sekaligus meminta arahan mengenai pemanfaatan sisa anggaran.","E":"Mencatat sisa anggaran sebagai pengeluaran untuk program lanjutan yang belum dilaksanakan agar penggunaan dana terlihat optimal, dengan komitmen merealisasikan kegiatan tersebut kemudian."}},{"id":11,"section":"TWK","stem":"Seorang petugas administrasi bertanggung jawab menyusun laporan inventaris peralatan laboratorium. Saat pemeriksaan, ia menemukan bahwa jumlah beberapa peralatan tidak sesuai dengan catatan sebelumnya. Kepala unit menjelaskan bahwa selisih tersebut kemungkinan disebabkan oleh peminjaman yang belum tercatat dan meminta petugas tetap menggunakan data lama agar laporan dapat diselesaikan tepat waktu. Kepala unit berjanji akan membantu menyelesaikan selisih tersebut setelah laporan dikumpulkan. Sikap yang paling mencerminkan integritas adalah ....","options":{"A":"Mencatat hasil pemeriksaan sesuai kondisi sebenarnya, melaporkan selisih yang ditemukan, dan mengusulkan penelusuran serta perbaikan administrasi melalui prosedur yang berlaku.","B":"Melakukan pemeriksaan ulang bersama petugas laboratorium untuk memperoleh kepastian jumlah peralatan sebelum menyelesaikan laporan inventaris.","C":"Meminta kepala unit memberikan keterangan tertulis mengenai kemungkinan penyebab selisih agar laporan memiliki dasar pertanggungjawaban yang jelas.","D":"Berkoordinasi dengan seluruh pengguna laboratorium untuk mengidentifikasi peralatan yang belum tercatat sehingga informasi inventaris dapat dilengkapi secara menyeluruh.","E":"Menyusun laporan sementara berdasarkan data yang telah diverifikasi sambil menunggu hasil penelusuran terhadap peralatan yang belum ditemukan."}},{"id":12,"section":"TWK","stem":"Seorang guru menemukan kesalahan penginputan nilai beberapa siswa setelah hasil ujian akhir diumumkan melalui sistem akademik sekolah. Kesalahan tersebut menyebabkan sebagian siswa memperoleh nilai lebih tinggi daripada hasil sebenarnya. Wakil kepala sekolah menyarankan agar nilai tidak diubah karena pengumuman sudah dilakukan dan perubahan dapat menimbulkan pertanyaan dari orang tua. Guru tersebut memahami kekhawatiran tersebut, tetapi menyadari bahwa nilai harus mencerminkan hasil penilaian yang sebenarnya. Sikap yang paling mencerminkan integritas adalah ....","options":{"A":"Melakukan pemeriksaan ulang terhadap seluruh nilai siswa untuk memastikan tidak terdapat kesalahan lain sebelum menentukan langkah perbaikan.","B":"Berkonsultasi dengan kepala sekolah mengenai dampak perubahan nilai agar keputusan yang diambil mempertimbangkan kepentingan siswa dan nama baik lembaga.","C":"Menyampaikan informasi kepada siswa yang terdampak mengenai kemungkinan kesalahan nilai dan memberikan kesempatan untuk mengajukan klarifikasi.","D":"Menmverifikasi kesalahan berdasarkan bukti penilaian, mengajukan koreksi melalui mekanisme resmi, serta memberikan penjelasan yang transparan kepada pihak terdampak.","E":"Mengadakan rapat bersama tim pengajar untuk mengevaluasi sistem penginputan nilai dan menyusun prosedur pencegahan kesalahan serupa pada masa mendatang."}},{"id":13,"section":"TWK","stem":"Seorang teknisi yang bekerja pada fasilitas penyediaan air bersih menemukan adanya kerusakan tidak wajar pada pengaman ruang pengendali utama. Ia juga melihat tanda-tanda bahwa seseorang mungkin telah memasuki area terbatas tanpa izin. Teknisi tersebut menyadari bahwa gangguan pada fasilitas tersebut dapat memengaruhi pasokan air bagi masyarakat luas. Ia tidak mencoba menghadapi pihak yang dicurigai, tetapi segera mengamankan pekerjaannya sesuai prosedur dan melaporkan temuan tersebut kepada petugas keamanan serta penanggung jawab fasilitas. Tindakan tersebut paling tepat menunjukkan ....","options":{"A":"Disiplin, karena teknisi mematuhi prosedur kerja dan segera melaksanakan kewajiban pelaporan ketika menemukan ketidaksesuaian.","B":"Integritas, karena teknisi menyampaikan kondisi yang ditemukan secara jujur tanpa menutupi potensi gangguan pada fasilitas tempatnya bekerja.","C":"Tanggung jawab sosial, karena teknisi memperhatikan kemungkinan dampak kerusakan fasilitas terhadap kebutuhan masyarakat luas.","D":"Bela negara, karena teknisi menunjukkan kewaspadaan dan turut melindungi fasilitas pelayanan penting yang berkaitan dengan keselamatan masyarakat dari potensi ancaman.","E":"Profesionalisme, karena teknisi memahami batas kewenangannya dan menyerahkan penanganan gangguan keamanan kepada petugas yang memiliki kompetensi."}},{"id":14,"section":"TWK","stem":"Seorang petugas teknis yang bekerja di pulau terluar Indonesia menemukan gangguan berulang pada sistem komunikasi yang digunakan untuk mendukung koordinasi pelayanan dan keamanan wilayah. Setelah melakukan pemeriksaan awal, ia menemukan adanya aktivitas akses yang tidak dikenal pada perangkat pengendali jaringan. Petugas tersebut belum dapat memastikan apakah gangguan disebabkan oleh kerusakan teknis atau tindakan pihak tertentu. Ia menyadari bahwa sistem komunikasi tersebut penting bagi kelancaran koordinasi di wilayah perbatasan. Tindakan yang paling mencerminkan bela negara adalah ....","options":{"A":"Mendokumentasikan indikasi gangguan sesuai prosedur, melaporkannya kepada pengelola sistem dan pihak keamanan yang berwenang, serta membantu langkah pengamanan sesuai kompetensi dan kewenangannya.","B":"Melakukan pemeriksaan teknis secara menyeluruh untuk memastikan penyebab gangguan sebelum menentukan tindakan yang dapat mengembalikan fungsi komunikasi.","C":"Berkoordinasi dengan petugas lain untuk meningkatkan pengawasan terhadap jaringan komunikasi dan memastikan pelayanan masyarakat tetap berlangsung.","D":"Menyampaikan kondisi gangguan kepada pimpinan unit disertai rekomendasi peningkatan keamanan perangkat agar risiko serupa dapat dicegah pada masa mendatang.","E":"Menyusun rencana penggunaan jalur komunikasi alternatif bersama petugas terkait agar koordinasi pelayanan di wilayah perbatasan tidak terhenti."}},{"id":15,"section":"TWK","stem":"Sebuah grup komunikasi warga menerima pesan suara yang terdengar seperti suara kepala desa. Pesan tersebut meminta masyarakat segera mengirimkan sejumlah uang ke rekening tertentu untuk membantu korban bencana. Beberapa warga mulai bersedia mentransfer karena mengenali suara dalam rekaman tersebut. Namun, seorang anggota grup menyadari bahwa nomor pengirim bukan nomor resmi pemerintah desa dan informasi penggalangan dana belum diumumkan melalui saluran resmi. Ia juga mengetahui bahwa teknologi kecerdasan buatan dapat digunakan untuk meniru suara seseorang. Sikap yang paling mencerminkan bela negara adalah ....","options":{"A":"Mengingatkan anggota grup agar menunda pengiriman uang, memverifikasi permintaan melalui saluran resmi pemerintah desa, dan melaporkan dugaan penipuan kepada pihak terkait setelah memperoleh informasi yang memadai.","B":"Menghubungi kepala desa secara pribadi untuk meminta klarifikasi mengenai pesan tersebut sebelum memberikan tanggapan kepada anggota grup lainnya.","C":"Memberikan edukasi kepada warga mengenai kemungkinan penyalahgunaan teknologi kecerdasan buatan dalam pembuatan pesan suara yang menyerupai tokoh masyarakat.","D":"Meminta pengurus grup membatasi penyebaran pesan tersebut sementara waktu dan mengarahkan anggota untuk memperoleh informasi melalui sumber yang dapat dipercaya.","E":"Mengumpulkan informasi mengenai asal pesan serta membandingkannya dengan pengumuman resmi agar dapat membantu masyarakat menilai keaslian permintaan bantuan."}},{"id":16,"section":"TWK","stem":"Seorang mahasiswa menerima informasi mengenai program beasiswa baru melalui grup komunikasi kampus. Pesan tersebut mencantumkan tautan pendaftaran yang meminta peserta masuk menggunakan akun akademik beserta kata sandinya. Informasi itu tampak meyakinkan karena menggunakan logo perguruan tinggi dan nama lembaga penyelenggara. Namun, mahasiswa tersebut tidak menemukan pengumuman serupa pada portal resmi kampus. Sikap yang paling mencerminkan bela negara adalah ....","options":{"A":"Memeriksa tampilan dan alamat situs pendaftaran untuk memastikan kesesuaiannya dengan identitas lembaga sebelum memasukkan informasi akun akademik.","B":"Menghubungi pengelola grup untuk menanyakan sumber informasi dan meminta penjelasan mengenai keabsahan program beasiswa yang dibagikan.","C":"Menunda pengisian data dan memverifikasi program melalui portal atau kontak resmi perguruan tinggi, serta melaporkan tautan apabila ditemukan indikasi penyalahgunaan identitas lembaga.","D":"Membandingkan informasi beasiswa dengan pengumuman program serupa dari lembaga pendidikan lain untuk mengetahui apakah persyaratan pendaftarannya wajar.","E":"Mengajak mahasiswa lain melakukan pemeriksaan bersama terhadap informasi program agar keputusan mengikuti pendaftaran didasarkan pada pertimbangan yang matang."}},{"id":17,"section":"TWK","stem":"Seorang kreator konten olahraga memiliki banyak pengikut dari kalangan remaja dan dewasa. Sebuah perusahaan menawarkan kerja sama berbayar untuk mempromosikan platform prediksi hasil pertandingan. Setelah mempelajari sistemnya, kreator tersebut mengetahui bahwa pengguna harus menyetorkan uang dan dapat memperoleh keuntungan berdasarkan hasil taruhan. Perusahaan menawarkan bayaran besar dan menjelaskan bahwa promosi dapat dikemas sebagai konten hiburan olahraga. Sikap yang paling mencerminkan bela negara adalah ....","options":{"A":"Menawarkan konsep promosi yang lebih edukatif dengan membahas analisis pertandingan dan mengurangi penekanan terhadap keuntungan finansial dari platform tersebut.","B":"Menolak kerja sama promosi karena berpotensi memperluas akses perjudian, serta memanfaatkan pengaruhnya untuk mengedukasi pengikut mengenai risiko aktivitas tersebut.","C":"Meminta perusahaan membatasi promosi hanya kepada pengguna dewasa dan menambahkan informasi mengenai risiko kehilangan uang dalam setiap konten.","D":"Mengusulkan agar platform menghilangkan unsur hadiah uang tunai dari materi promosi sehingga konten lebih menonjolkan aspek hiburan dan kemampuan analisis olahraga.","E":"Mempertimbangkan kerja sama dengan ketentuan sebagian keuntungan digunakan untuk kegiatan sosial serta seluruh konten disertai pesan mengenai pengelolaan keuangan yang bijaksana."}},{"id":18,"section":"TWK","stem":"Di sebuah perusahaan, seorang pegawai mengetahui bahwa beberapa rekan kerjanya sering membagikan tautan permainan judi online melalui grup komunikasi informal. Salah satu rekannya bahkan mengajak pegawai lain bergabung menggunakan kode referal dengan alasan dapat memperoleh penghasilan tambahan. Pegawai tersebut menyadari bahwa kebiasaan ini mulai memengaruhi konsentrasi kerja beberapa anggota tim. Ia ingin membantu tanpa mempermalukan rekan-rekannya di hadapan pegawai lain. Sikap yang paling mencerminkan bela negara adalah ....","options":{"A":"Mengajak rekan kerja berdiskusi mengenai pentingnya menjaga produktivitas dan mengelola keuangan agar aktivitas pribadi tidak memengaruhi pekerjaan.","B":"Mengusulkan kepada pengelola grup agar menetapkan ketentuan yang membatasi penyebaran tautan permainan berisiko selama komunikasi yang berkaitan dengan pekerjaan.","C":"Melakukan pendekatan secara pribadi untuk menjelaskan risiko perjudian, meminta penghentian penyebaran tautan, serta menggunakan mekanisme pelaporan yang sesuai apabila aktivitas promosi tetap berlangsung.","D":"Mengarahkan rekan kerja kepada kegiatan produktif yang dapat memberikan tambahan penghasilan secara legal agar ketertarikan terhadap perjudian dapat berkurang.","E":"Mengusulkan kegiatan literasi keuangan dan keamanan digital di lingkungan perusahaan agar seluruh pegawai lebih memahami risiko aktivitas finansial daring."}},{"id":19,"section":"TWK","stem":"Sebuah perusahaan teknologi membuka lowongan pekerjaan untuk posisi pengembang perangkat lunak. Dalam proses seleksi awal, perusahaan lebih mengutamakan lulusan perguruan tinggi ternama karena dianggap memiliki kualitas pendidikan yang lebih baik. Namun, sejumlah pelamar dari perguruan tinggi daerah dan jalur pendidikan nonformal memiliki kemampuan pemrograman serta portofolio yang sangat baik. Jika dikaitkan dengan nilai Pancasila, kebijakan rekrutmen yang paling tepat adalah ....","options":{"A":"Memberikan kesempatan kepada pelamar dari berbagai latar belakang pendidikan untuk mengikuti seleksi dengan tetap mempertimbangkan reputasi institusi pendidikan sebagai salah satu indikator kualitas.","B":"Mengembangkan proses seleksi berbasis kompetensi dan bukti kemampuan yang relevan dengan pekerjaan, sehingga pelamar dari berbagai latar belakang pendidikan memperoleh kesempatan dinilai secara objektif.","C":"Menyediakan jalur seleksi tambahan bagi lulusan perguruan tinggi daerah agar mereka memiliki kesempatan menunjukkan kemampuan tanpa harus bersaing langsung dengan lulusan perguruan tinggi ternama.","D":"Mengadakan program pelatihan persiapan kerja bagi pelamar dari institusi pendidikan yang kurang dikenal untuk meningkatkan kesiapan mereka dalam menghadapi standar perusahaan.","E":"Menjalin kerja sama rekrutmen dengan berbagai perguruan tinggi di daerah agar perusahaan dapat menjangkau lebih banyak kandidat yang memiliki potensi dan keterampilan."}},{"id":20,"section":"TWK","stem":"Pemerintah kota berencana memperbarui sistem transportasi umum agar lebih nyaman dan modern. Namun, hasil survei menunjukkan bahwa penyandang disabilitas dan sebagian lansia masih mengalami kesulitan menggunakan layanan tersebut karena keterbatasan akses pada halte, kendaraan, dan fasilitas informasi. Sebagian pengelola mengusulkan agar anggaran diprioritaskan untuk meningkatkan kapasitas kendaraan pada rute dengan jumlah penumpang terbesar. Kebijakan yang paling mencerminkan nilai Pancasila adalah ....","options":{"A":"Meningkatkan kapasitas kendaraan pada rute dengan jumlah pengguna tertinggi sambil mengembangkan fasilitas khusus bagi penumpang yang membutuhkan bantuan tambahan.","B":"Memberikan potongan tarif kepada penyandang disabilitas dan lansia agar mereka memperoleh dukungan ekonomi dalam menggunakan transportasi umum.","C":"Menyelenggarakan pelatihan pelayanan inklusif bagi pengemudi dan petugas agar seluruh penumpang memperoleh bantuan yang sesuai dengan kebutuhannya.","D":"Menyusun pengembangan transportasi berdasarkan hambatan akses yang dialami berbagai kelompok, termasuk penyesuaian fasilitas dan layanan agar seluruh masyarakat memiliki kesempatan yang layak untuk menggunakannya.","E":"Mengembangkan layanan transportasi pendamping bagi kelompok masyarakat berkebutuhan khusus untuk membantu mereka menjangkau fasilitas pendidikan, kesehatan, dan pelayanan publik."}},{"id":21,"section":"TWK","stem":"Sebuah perusahaan jasa membuka lowongan pekerjaan yang dapat dilaksanakan melalui komputer. Salah satu pelamar merupakan penyandang disabilitas pendengaran dengan kemampuan teknis dan pengalaman yang sesuai dengan posisi tersebut. Namun, tahapan wawancara perusahaan selama ini dilakukan secara lisan melalui panggilan video tanpa fasilitas pendukung komunikasi. Tim rekrutmen khawatir perubahan mekanisme wawancara akan membuat proses seleksi menjadi kurang seragam. Kebijakan yang paling sesuai dengan nilai Pancasila adalah","options":{"A":"Memberikan kesempatan kepada pelamar untuk menyampaikan kemampuan dan pengalamannya melalui dokumen tertulis sebagai pelengkap proses seleksi yang telah ditetapkan.","B":"Mengembangkan pelatihan bagi tim rekrutmen mengenai komunikasi inklusif agar seluruh pewawancara mampu berinteraksi dengan pelamar yang memiliki kebutuhan berbeda.","C":"Menawarkan wawancara dengan pendamping komunikasi agar pelamar dapat menyampaikan jawaban secara jelas tanpa mengubah seluruh tahapan seleksi perusahaan.","D":"Menyediakan penyesuaian metode wawancara yang aksesibel sesuai kebutuhan pelamar dengan tetap menggunakan standar kompetensi pekerjaan yang sama bagi seluruh kandidat.","E":"Mengembangkan kebijakan rekrutmen inklusif secara bertahap melalui peningkatan fasilitas, pendampingan pelamar, dan evaluasi terhadap hambatan seleksi."}},{"id":22,"section":"TWK","stem":"Perkembangan teknologi kecerdasan buatan menimbulkan berbagai persoalan baru, termasuk penyalahgunaan identitas digital dan penyebaran konten manipulatif. DPR menerima banyak aspirasi masyarakat yang meminta adanya perlindungan hukum lebih jelas terhadap penggunaan teknologi tersebut. Menanggapi kondisi ini, DPR bersama pemerintah mulai membahas rancangan undang-undang yang akan mengatur hak, kewajiban, dan tanggung jawab pihak-pihak yang mengembangkan maupun menggunakan teknologi kecerdasan buatan. Berdasarkan Pasal 20A UUD NRI Tahun 1945, kegiatan tersebut paling tepat mencerminkan ....","options":{"A":"Fungsi pengawasan karena DPR mengidentifikasi persoalan dalam masyarakat yang muncul akibat perkembangan teknologi dan menilai kebutuhan perlindungan warga negara.","B":"Fungsi legislasi karena DPR menjalankan kewenangannya dalam pembentukan undang-undang untuk memberikan landasan hukum terhadap perkembangan dan penggunaan teknologi.","C":"Fungsi anggaran karena pembentukan kebijakan baru dapat memerlukan pembiayaan negara untuk mendukung pengawasan dan pelaksanaannya.","D":"Fungsi representasi karena DPR menindaklanjuti aspirasi masyarakat yang menginginkan peningkatan perlindungan terhadap penggunaan teknologi digital.","E":"Fungsi pengawasan karena DPR berupaya memastikan perkembangan teknologi tidak menimbulkan dampak yang merugikan kepentingan masyarakat."}},{"id":23,"section":"TWK","stem":"Pemerintah menjalankan program subsidi transportasi umum untuk membantu masyarakat berpenghasilan rendah. Program tersebut telah memperoleh alokasi anggaran negara dan mulai dilaksanakan di sejumlah wilayah. Setelah pelaksanaan berjalan, DPR menemukan bahwa sebagian penerima manfaat masih membayar tarif yang lebih tinggi daripada ketentuan program. DPR kemudian meminta laporan realisasi subsidi dari kementerian terkait, menelusuri penyebab ketidaksesuaian, serta mendorong perbaikan mekanisme penyaluran. Fungsi DPR yang paling dominan dalam kegiatan tersebut adalah ....","options":{"A":"Fungsi anggaran karena DPR memastikan bahwa dana subsidi yang telah dialokasikan dalam APBN digunakan untuk mendukung kebutuhan masyarakat.","B":"Fungsi legislasi karena DPR menilai apakah pelaksanaan subsidi telah sesuai dengan peraturan yang menjadi dasar penyelenggaraan program.","C":"Fungsi representasi karena DPR memperjuangkan kepentingan masyarakat berpenghasilan rendah yang belum memperoleh manfaat subsidi secara optimal.","D":"Fungsi pengawasan karena DPR menilai kesesuaian antara ketentuan dan realisasi program pemerintah serta meminta tindak lanjut terhadap penyimpangan pelaksanaan.","E":"Fungsi anggaran karena DPR melakukan evaluasi terhadap penggunaan dana subsidi sebagai bahan pertimbangan penyusunan anggaran pada periode berikutnya."}},{"id":24,"section":"TWK","stem":"Seorang warga mengikuti persidangan pengujian undang-undang di Mahkamah Konstitusi. Ia kemudian menemukan dugaan bahwa salah satu hakim konstitusi memiliki konflik kepentingan yang tidak diungkapkan dalam penanganan perkara tersebut. Warga tersebut berencana melaporkan dugaan pelanggaran etik kepada Komisi Yudisial karena menganggap lembaga tersebut bertugas mengawasi seluruh hakim di Indonesia. Berdasarkan sistem ketatanegaraan Indonesia, langkah yang paling tepat adalah ....","options":{"A":"Menyampaikan laporan kepada Komisi Yudisial agar dilakukan pemeriksaan bersama Mahkamah Konstitusi karena KY memiliki kewenangan umum menjaga etika seluruh hakim.","B":"Mengajukan laporan dugaan pelanggaran etik melalui mekanisme Majelis Kehormatan Mahkamah Konstitusi (MKMK), karena pengawasan etik hakim konstitusi tidak termasuk kewenangan Komisi Yudisial.","C":"Meminta Komisi Yudisial memberikan rekomendasi kepada DPR agar dilakukan evaluasi terhadap hakim konstitusi yang diduga memiliki konflik kepentingan.","D":"Mengajukan permohonan kepada Mahkamah Agung untuk menilai dugaan pelanggaran etik hakim konstitusi sebagai bagian dari pengawasan kekuasaan kehakiman.","E":"Meminta Komisi Yudisial melakukan klarifikasi awal terhadap dugaan konflik kepentingan sebelum menyerahkan hasilnya kepada Mahkamah Konstitusi untuk diproses lebih lanjut."}},{"id":25,"section":"TWK","stem":"(1) Perkembangan layanan keuangan digital perlu diimbangi dengan peningkatan literasi keuangan masyarakat, terutama generasi muda. (2) Kemudahan melakukan pembayaran melalui aplikasi membuat berbagai transaksi dapat diselesaikan hanya dalam beberapa detik. (3) Namun, penawaran diskon dan promosi yang terus muncul dapat mendorong perilaku konsumtif apabila pengguna tidak mampu mengendalikan pengeluarannya. (4) Pemahaman mengenai penyusunan anggaran pribadi diperlukan agar seseorang dapat membedakan kebutuhan dan keinginan. (5) Selain itu, pengetahuan tentang keamanan akun dan perlindungan data pribadi juga penting untuk mengurangi risiko penyalahgunaan layanan keuangan digital. (6) Oleh karena itu, kemampuan mengelola keuangan secara bijak menjadi bekal penting dalam memanfaatkan kemajuan teknologi finansial. Gagasan utama paragraf tersebut adalah ....","options":{"A":"Perkembangan teknologi pembayaran digital yang memberikan kemudahan dalam melakukan berbagai transaksi keuangan.","B":"Pentingnya pengelolaan anggaran pribadi untuk mencegah perilaku konsumtif akibat penawaran promosi digital.","C":"Pentingnya peningkatan literasi keuangan agar masyarakat mampu memanfaatkan layanan keuangan digital secara bijak dan bertanggung jawab.","D":"Perlunya perlindungan data pribadi dan keamanan akun dalam menghadapi risiko penggunaan aplikasi keuangan digital.","E":"Pengaruh kemudahan transaksi dan strategi promosi digital terhadap perubahan perilaku konsumsi generasi muda."}},{"id":26,"section":"TWK","stem":"(1) Pemanfaatan lahan kosong untuk kebun komunitas dapat memberikan berbagai manfaat bagi kehidupan masyarakat perkotaan. (2) Lahan yang sebelumnya tidak terawat dapat diubah menjadi tempat penanaman sayuran dan tanaman produktif lainnya. (3) Hasil panen dari kebun tersebut dapat digunakan untuk memenuhi sebagian kebutuhan pangan warga. (4) Selain itu, kegiatan berkebun bersama memberikan kesempatan kepada masyarakat untuk berinteraksi dan memperkuat hubungan sosial. (5) Anak-anak juga dapat memperoleh pengalaman langsung mengenai proses pertumbuhan tanaman serta pentingnya menjaga lingkungan. (6) Pengelolaan kebun komunitas secara bersama-sama dapat meningkatkan rasa tanggung jawab warga terhadap fasilitas lingkungan. (7) Beberapa kelompok masyarakat bahkan mulai memanfaatkan hasil panen untuk mendukung kegiatan sosial di wilayah tempat tinggal mereka. Kalimat utama paragraf tersebut terdapat pada nomor ....","options":{"A":"-2","B":"-4","C":"-1","D":"-6","E":"-7"}},{"id":27,"section":"TWK","stem":"(1) Pemerintah kota telah menambah jumlah armada bus untuk meningkatkan penggunaan transportasi umum. (2) Penambahan tersebut membuat kapasitas angkutan penumpang menjadi lebih besar dibandingkan sebelumnya. (3) Namun, hasil evaluasi menunjukkan bahwa peningkatan jumlah penumpang belum sesuai dengan target yang ditetapkan. (4) Sebagian masyarakat menyampaikan bahwa lokasi halte masih sulit dijangkau dan waktu kedatangan bus belum dapat diperkirakan secara konsisten. (5) Pemerintah kemudian berencana meninjau kembali rute perjalanan, lokasi pemberhentian, dan pengaturan jadwal agar layanan transportasi lebih sesuai dengan kebutuhan pengguna. Kesimpulan yang paling tepat untuk paragraf tersebut adalah ....","options":{"A":"Peningkatan kapasitas transportasi umum perlu disertai evaluasi terhadap pola perjalanan masyarakat agar penambahan armada dapat dimanfaatkan secara lebih efektif.","B":"Keberhasilan pengembangan transportasi umum tidak hanya bergantung pada penambahan armada, tetapi juga pada keterjangkauan akses dan keandalan layanan sesuai kebutuhan masyarakat.","C":"Kemudahan menjangkau halte dan kepastian jadwal perjalanan merupakan faktor penting yang dapat memengaruhi minat masyarakat menggunakan transportasi umum.","D":"Pemerintah perlu menyesuaikan pengelolaan rute serta jadwal bus berdasarkan hasil evaluasi agar kualitas pelayanan transportasi terus mengalami peningkatan.","E":"Penyediaan fasilitas transportasi umum yang memadai perlu diimbangi dengan perencanaan pelayanan yang mempertimbangkan karakteristik perjalanan pengguna."}},{"id":28,"section":"TWK","stem":"Manakah di antara kalimat-kalimat berikut yang merupakan kalimat efektif?","options":{"A":"Guru memberikan umpan balik tertulis agar siswa dapat memperbaiki hasil pekerjaannya berdasarkan kesalahan yang ditemukan.","B":"Bagi siswa yang belum mengumpulkan tugas diminta segera menemui wali kelas untuk memperoleh penjelasan mengenai ketentuan pengumpulan.","C":"Setiap siswa wajib harus mengisi formulir pendaftaran sebelum mengikuti kegiatan pembelajaran tambahan yang diselenggarakan sekolah.","D":"Hasil daripada penilaian menunjukkan bahwa sebagian peserta telah memahami materi, sedangkan peserta lainnya masih memerlukan pendampingan.","E":"Walaupun waktu yang tersedia cukup terbatas, tetapi seluruh peserta tetap dapat menyelesaikan kegiatan sesuai ketentuan yang ditetapkan."}},{"id":29,"section":"TWK","stem":"Panitia Festival Cita Rasa Nusantara sedang menyusun katalog yang akan dibagikan kepada pengunjung. Sebelum dicetak, seorang editor diminta memeriksa ketepatan penggunaan huruf kapital dalam deskripsi kegiatan. Manakah kalimat berikut yang salah dalam penggunaan huruf kapital?","options":{"A":"Panitia menyajikan bubur Manado di stan kuliner Sulawesi Utara.","B":"Pengunjung dapat mencicipi satai Madura dan kopi Gayo yang disediakan peserta.","C":"Minuman tradisional tersebut diberi tambahan gula Jawa agar rasanya lebih nikmat.","D":"Festival dibuka oleh Gubernur Jawa Tengah di Kota Semarang.","E":"Pada hari Sabtu, kelompok seni akan menampilkan tari Bali untuk menghibur pengunjung."}},{"id":30,"section":"TWK","stem":"Sebuah universitas mengadakan program pemeriksaan kesehatan gratis bagi mahasiswa. Setelah kegiatan selesai, panitia menyusun laporan yang memuat proses pendaftaran, pelaksanaan pemeriksaan, dan evaluasi program. (1) Petugas administrasi bertanggung jawab memverifikasi identitas peserta sebelum pemeriksaan. (2) Panitia terus menghimbau mahasiswa agar mengikuti prosedur pemeriksaan sesuai jadwal. (3) Relawan bertugas mendistribusikan masker dan perlengkapan kesehatan kepada seluruh peserta. (4) Tim medis akan menganalisis hasil pemeriksaan untuk mengidentifikasi masalah kesehatan yang dominan. (5) Pihak universitas berkomitmen menyediakan layanan konsultasi kesehatan lanjutan bagi mahasiswa. Kata tidak baku terdapat pada....","options":{"A":"Memverifikasi (kalimat 1)","B":"Menghimbau (kalimat 2)","C":"Mendistribusikan (kalimat 3)","D":"Menganalisis (kalimat 4)","E":"Menyediakan (kalimat 5)"}},{"id":31,"section":"TIU","stem":"KOMPONIS : LAGU = .... : ....","options":{"A":"Pelukis - Lukisan","B":"Guru - Sekolah","C":"Dokter- Pasien","D":"Petani- Sawah","E":"Pembaca - Buku"}},{"id":32,"section":"TIU","stem":"SUARA : PELAN : KERAS = .... : .... : ....","options":{"A":"Cahaya: Redup: Terang","B":"Air: Jernih: Keruh","C":"Jalan: Sempit : Panjang","D":"Udara: Dingin: Basah","E":"Api: Padam: Asap"}},{"id":33,"section":"TIU","stem":"Hubungan objek pada kalimat “Tono menggunakan palu untuk memasang paku\" setara dengan....","options":{"A":"Rina membawa buku ke sekolah.","B":"Sinta menggunakan gunting untuk memotong kertas.","C":"Dodi membeli meja dan kursi.","D":"Bima menyimpan pakaian di lemari.","E":"Andi membaca koran pada pagi hari."}},{"id":34,"section":"TIU","stem":"Tidak ada makanan organik yang menggunakan pestisida sintetis. Semua sayuran di Toko Sehat merupakan makanan organik. Kesimpulan yang paling tepat adalah ....","options":{"A":"Sebagian sayuran di Toko Sehat menggunakan pestisida sintetis.","B":"Semua makanan organik dijual di Toko Sehat.","C":"Semua sayuran di Toko Sehat tidak menggunakan pestisida sintetis.","D":"Sebagian makanan organik bukan sayuran.","E":"Tidak dapat disimpulkan."}},{"id":35,"section":"TIU","stem":"Semua pegawai divisi keuangan telah mengikuti pelatihan perpajakan. Sebagian pegawai divisi keuangan merupakan pegawai baru. Kesimpulan yang tepat adalah ....","options":{"A":"Sebagian pegawai baru belum mengikuti pelatihan perpajakan.","B":"Semua pegawai baru berada di divisi keuangan.","C":"Sebagian pegawai yang telah mengikuti pelatihan perpajakan merupakan pegawai baru.","D":"Semua peserta pelatihan perpajakan merupakan pegawai baru.","E":"Tidak ada pegawai baru yang mengikuti pelatihan perpajakan."}},{"id":36,"section":"TIU","stem":"Penggunaan aplikasi belajar daring diyakini dapat meningkatkan hasil belajar siswa karena materi dapat diakses kapan saja dan siswa dapat mengulang pelajaran yang belum dipahami. Oleh karena itu, semakin sering siswa menggunakan aplikasi belajar daring, semakin tinggi hasil belajarnya. Manakah pernyataan berikut yang PALING MELEMAHKAN argumen tersebut?","options":{"A":"Banyak aplikasi belajar menyediakan video dan latihan soal interaktif.","B":"Sebagian siswa lebih menyukai belajar menggunakan buku cetak.","C":"Siswa yang terlalu sering menggunakan aplikasi belajar justru sering terdistraksi oleh notifikasi dan konten lain di perangkatnya.","D":"Beberapa sekolah menyediakan akses internet gratis bagi siswanya.","E":"Aplikasi belajar dapat digunakan baik melalui ponsel maupun komputer."}},{"id":37,"section":"TIU","stem":"Argumen 1: Penggunaan tablet dalam pembelajaran dapat meningkatkan pemahaman siswa karena materi dapat disajikan secara interaktif. Argumen 2: Pemahaman siswa lebih efektif ditingkatkan melalui diskusi langsung dengan guru dan teman sekelas. Fakta di lapangan: Hasil evaluasi menunjukkan bahwa siswa yang menggunakan tablet tanpa pendampingan guru tidak mengalami peningkatan nilai yang berarti, sedangkan siswa yang rutin mengikuti diskusi kelas menunjukkan peningkatan pemahaman yang lebih besar. Simpulan mengenai fakta tersebut adalah ....","options":{"A":"Memperkuat argumen 1","B":"Memperlemah argumen 1 dan memperkuat argumen 2","C":"Memperlemah argumen 2","D":"Memperkuat kedua argumen","E":"Tidak berhubungan dengan kedua argumen"}},{"id":38,"section":"TIU","stem":"Semua mahasiswa yang mengikuti program pertukaran memperoleh kartu akses internasional. Semua mahasiswa Fakultas Ekonomi mengikuti program pertukaran. Kesimpulan: (1) Semua mahasiswa Fakultas Ekonomi memperoleh kartu akses internasional. (2) Semua mahasiswa yang memperoleh kartu akses internasional berasal dari Fakultas Ekonomi. Pernyataan yang tepat adalah....","options":{"A":"Hanya kesimpulan (1) yang tepat","B":"Hanya kesimpulan (2) yang tepat","C":"Kesimpulan (1) dan (2) keduanya tepat","D":"Kesimpulan (1) atau (2) tepat","E":"Baik kesimpulan (1) maupun (2) tidak tepat"}},{"id":39,"section":"TIU","stem":"Dalam lomba renang, Raka berenang lebih cepat daripada Dimas. Fani mencatat waktu tercepat. Sinta lebih cepat daripada Raka. Bima lebih lambat daripada Dimas, tetapi lebih cepat daripada Tono. Urutan peserta dari yang tercepat hingga terlambat adalah ....","options":{"A":"Fani, Sinta, Raka, Dimas, Bima, Tono","B":"Fani, Raka, Sinta, Dimas, Bima, Tono","C":"Sinta, Fani, Raka, Bima, Dimas, Tono","D":"Fani, Sinta, Dimas, Raka, Bima, Tono","E":"Fani, Sinta, Raka, Bima, Dimas, Tono"}},{"id":40,"section":"TIU","stem":"Lima siswa, yaitu Fajar, Gina, Hana, Indra, dan Joko, tinggal di sepanjang satu jalan menuju sekolah. Siswa yang rumahnya paling jauh dari sekolah menjemput teman lainnya saat berangkat. Diketahui: Joko tinggal paling jauh dari sekolah; Hana dijemput setelah Fajar; rumah Gina berada di antara rumah Fajar dan Hana; Indra adalah siswa terakhir yang dijemput. Urutan rumah dari yang terdekat dengan sekolah adalah ....","options":{"A":"Indra - Gina - Hana - Fajar - Joko","B":"Hana - Indra - Gina - Fajar - Joko","C":"Indra - Hana - Gina - Fajar - Joko","D":"Indra - Hana- Fajar - Gina - Joko","E":"Fajar - Gina - Hana - Indra - Joko"}},{"id":41,"section":"TIU","stem":"Enam orang, yaitu Gita, Hana, Intan, Joko, Karin, dan Luki, sedang duduk melingkar menghadap ke tengah meja. Gita duduk tepat di antara Luki dan Hana. Joko duduk tepat di sebelah kanan Karin. Hana duduk tepat di sebelah kiri Gita. Jika Intan duduk tepat di sebelah kanan Joko, maka Karin duduk tepat di antara ....","options":{"A":"Gita dan Hana","B":"Intan dan Joko","C":"Joko dan Luki","D":"Hana dan Intan","E":"Luki dan Gita"}},{"id":42,"section":"TIU","stem":"Sebuah gudang membagi barang ke dalam beberapa kontainer secara merata. Kombinasi pembagian yang menghasilkan jumlah barang per kontainer yang sama adalah ....","options":{"A":"960 ÷ 30 sama dengan 1200 ÷ 40","B":"1170 ÷ 30 sama dengan 1440 ÷ 36","C":"1320 ÷ 33 sama dengan 1500 ÷ 30","D":"1440 ÷ 32 sama dengan 1800 ÷ 40","E":"1680 ÷ 35 sama dengan 2000 ÷ 40"}},{"id":43,"section":"TIU","stem":"Hasil operasi yang sama dengan 864 ÷ 24 adalah ....","options":{"A":"600 ÷ 20","B":"720 ÷ 24","C":"900 ÷ 25","D":"840 ÷ 28","E":"960 ÷ 30"}},{"id":44,"section":"TIU","stem":"Sebuah gudang akan mengemas sejumlah produk ke dalam beberapa kotak secara merata. Kombinasi pembagian yang menghasilkan jumlah produk per kotak yang sama adalah ....","options":{"A":"840 ÷ 21 sama dengan 1080 ÷ 27","B":"900 ÷ 25 sama dengan 1200 ÷ 30","C":"960 ÷ 24 sama dengan 1260 ÷ 28","D":"1050 ÷ 30 sama dengan 1400 ÷ 35","E":"1320 ÷ 33 sama dengan 1500 ÷ 30"}},{"id":45,"section":"TIU","stem":"Sebuah pabrik minuman mencatat jumlah botol yang diproduksi oleh beberapa mesin. Pasangan perhitungan yang menghasilkan jumlah botol yang sama adalah ....","options":{"A":"26 × 40 sama dengan 1080 ÷ 1","B":"30 × 36 sama dengan 2160 ÷ 2","C":"28 × 32 sama dengan 1728 ÷ 2","D":"35 × 24 sama dengan 1800 ÷ 2","E":"42 × 20 sama dengan 1760 ÷ 2"}},{"id":46,"section":"TIU","stem":"Hasil operasi yang sama dengan 432 ÷ 18 adalah ....","options":{"A":"360 ÷ 18","B":"504 ÷ 21","C":"600 ÷ 20","D":"672 ÷ 24","E":"750 ÷ 25"}},{"id":47,"section":"TIU","stem":"Berapakah nilai x? (1) x + 4 = 11. (2) x merupakan bilangan genap yang lebih besar dari 5 dan lebih kecil dari 9.","options":{"A":"Pernyataan (1) SAJA cukup, tetapi pernyataan (2) saja tidak cukup.","B":"Pernyataan (2) SAJA cukup, tetapi pernyataan (1) saja tidak cukup.","C":"Kedua pernyataan BERSAMA-SAMA cukup, tetapi SATU pernyataan SAJA tidak cukup.","D":"Masing-masing pernyataan (1) maupun (2) saja sudah cukup.","E":"Kedua pernyataan, baik sendiri-sendiri maupun bersama-sama, tidak cukup."}},{"id":48,"section":"TIU","stem":"Berapakah waktu yang dibutuhkan sebuah mobil untuk menempuh suatu perjalanan? (1) Jarak perjalanan adalah 300 km. (2) Kecepatan rata-rata mobil adalah 75 km/jam.","options":{"A":"Pernyataan (1) saja cukup, tetapi pernyataan (2) saja tidak cukup.","B":"Pernyataan (2) saja cukup, tetapi pernyataan (1) saja tidak cukup.","C":"Kedua pernyataan bersama-sama cukup, tetapi masing-masing pernyataan saja tidak cukup.","D":"Masing-masing pernyataan (1) maupun (2) saja sudah cukup.","E":"Kedua pernyataan, baik sendiri-sendiri maupun bersama-sama, tidak cukup."}},{"id":49,"section":"TIU","stem":"Panitia study tour menyediakan pilihan paket kendaraan berikut. Ketentuan: (1) Kegiatan diikuti tepat 210 peserta. (2) Total kapasitas kendaraan tidak boleh melebihi jumlah peserta. (3) Setiap peserta harus mendapatkan tempat. (4) Panitia ingin memilih kombinasi dengan biaya paling hemat. Kombinasi paket yang paling hemat adalah ....","options":{"A":"6 paket Arjuna","B":"5 paket Bima","C":"3 paket Cakra","D":"2 paket Arjuna dan 2 paket Cakra","E":"4 paket Arjuna dan 1 paket Cakra"},"table":{"headers":["Paket","Kapasitas","Harga"],"rows":[["Arjuna","35 orang","Rp3.500.000"],["Bima","42 orang","Rp3.780.000"],["Cakra","70 orang","Rp5.950.000"]]}},{"id":50,"section":"TIU","stem":"Panitia kegiatan kampus harus menyediakan kendaraan untuk tepat 300 mahasiswa. Ketentuan: (1) Seluruh mahasiswa harus memperoleh tempat duduk. (2) Total kapasitas harus tepat 300 orang. (3) Panitia memilih kombinasi dengan biaya paling rendah. Kombinasi yang paling hemat adalah ....","options":{"A":"12 Van","B":"6 Bus Sedang","C":"4 Bus Besar","D":"6 Van dan 2 Bus Besar","E":"2 Van, 2 Bus Sedang, dan 2 Bus Besar"},"table":{"headers":["Paket","Kapasitas","Harga"],"rows":[["Van","25 orang","Rp2.250.000"],["Bus Sedang","50 orang","Rp4.100.000"],["Bus Besar","75 orang","Rp5.700.000"]]}},{"id":51,"section":"TIU","stem":"Sebuah mesin mengemas produk dengan jumlah yang dihasilkan sebanding dengan waktu kerja. Perhatikan tabel berikut. (1) Mesin menghasilkan 150 produk per jam. (2) Berdasarkan tabel, jumlah produk berbanding senilai dengan waktu kerja. Nilai x adalah ....","options":{"A":"Pernyataan (1) saja cukup, tetapi pernyataan (2) saja tidak cukup.","B":"Pernyataan (2) saja cukup, tetapi pernyataan (1) saja tidak cukup.","C":"Kedua pernyataan bersama-sama cukup, tetapi masing-masing pernyataan saja tidak cukup.","D":"Masing-masing pernyataan (1) maupun (2) saja sudah cukup.","E":"Kedua pernyataan, baik sendiri-sendiri maupun bersama-sama, tidak cukup."},"table":{"headers":["Waktu Kerja","Jumlah Produk"],"rows":[["5 jam","750 produk"],["8 jam","x produk"]]}},{"id":52,"section":"TIU","stem":"Perhatikan tabel berikut. Berapakah tinggi segitiga tersebut? Pernyataan (1): Alas segitiga adalah 12 cm. Pernyataan (2): Luas segitiga adalah 54 cm².","options":{"A":"Pernyataan (1) saja cukup, tetapi pernyataan (2) saja tidak cukup.","B":"Pernyataan (2) saja cukup, tetapi pernyataan (1) saja tidak cukup.","C":"Kedua pernyataan bersama-sama cukup, tetapi masing-masing pernyataan saja tidak cukup.","D":"Masing-masing pernyataan (1) maupun (2) saja sudah cukup.","E":"Kedua pernyataan, baik sendiri-sendiri maupun bersama-sama, tidak cukup."},"table":{"headers":["Ukuran Segitiga","Nilai"],"rows":[["Alas","a cm"],["Tinggi","t cm"],["Luas","L cm²"]]}},{"id":53,"section":"TIU","stem":"Sebuah toko memberikan diskon pada sebuah jaket. Berapakah harga jaket setelah diskon? (1) Harga awal jaket adalah Rp750.000. (2) Toko memberikan diskon 20%.","options":{"A":"Cukup (1)","B":"Cukup (2)","C":"Pernyataan (1) dan (2) harus digunakan bersama-sama","D":"Menggunakan pernyataan (1) saja atau (2) saja sudah cukup","E":"Kedua pernyataan tidak cukup"}},{"id":54,"section":"TIU","stem":"Sebuah toko menjual dua jenis paket makanan, yaitu Paket A dan Paket B. Berapakah total pendapatan toko dari penjualan seluruh paket? (1) Jumlah Paket A dan Paket B yang terjual adalah 300 paket. (2) Paket B yang terjual 40 paket lebih banyak daripada Paket A.","options":{"A":"Pernyataan (1) SAJA cukup, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup, tetapi pernyataan (1) SAJA tidak cukup.","C":"DUA pernyataan BERSAMA-SAMA cukup, tetapi SATU pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup dan pernyataan (2) SAJA juga cukup.","E":"Kedua pernyataan tidak cukup."},"table":{"headers":["Jenis Paket","Harga/Paket","Jumlah Terjual"],"rows":[["Paket A","Rp180.000","x"],["Paket B","Rp120.000","y"]]}},{"id":55,"section":"TIU","stem":"Perhatikan tabel penjualan minuman berikut. Pernyataan yang benar berdasarkan tabel adalah ....","options":{"A":"Es Kopi menghasilkan pendapatan sebesar Rp540.000.","B":"Jus Mangga memiliki pendapatan terbesar.","C":"Cokelat terjual paling sedikit.","D":"Pendapatan Air Mineral lebih besar daripada Teh Tarik.","E":"Jumlah Es Kopi dan Jus Mangga yang terjual adalah 60 gelas."},"table":{"headers":["Jenis Minuman","Jumlah Terjual","Harga per Gelas"],"rows":[["Es Kopi","36 gelas","Rp15.000"],["Teh Tarik","40 gelas","Rp10.000"],["Jus Mangga","25 gelas","Rp18.000"],["Cokelat","30 gelas","Rp16.000"],["Air Mineral","50 botol","Rp5.000"]]}},{"id":56,"section":"TIU","stem":"Perhatikan tabel berikut. Nilai p yang tepat untuk melengkapi pola pada tabel adalah ....","options":{"A":"19","B":"21","C":"23","D":"25","E":"27"},"table":{"headers":["Kolom 1","Kolom 2","Kolom 3"],"rows":[["4","7","p"],["8","5","69"],["6","3","39"]]}},{"id":57,"section":"TIU","stem":"Perhatikan tabel berikut. Nilai x yang tepat untuk melengkapi pola pada tabel adalah ....","options":{"A":"115","B":"117","C":"119","D":"121","E":"123"},"table":{"headers":["Suku ke-","Nilai"],"rows":[["3","11"],["6","23"],["10","39"],["18","71"],["30","x"]]}},{"id":58,"section":"TIU","stem":"Perhatikan tabel berikut. Nilai 68 terdapat pada urutan ke- ....","options":{"A":"9","B":"10","C":"11","D":"12","E":"13"},"table":{"headers":["Suku ke-","Nilai"],"rows":[["1","8"],["2","14"],["3","20"],["4","26"]]}},{"id":59,"section":"TIU","stem":"Carilah gambar yang berbeda.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q59"},{"id":60,"section":"TIU","stem":"Carilah gambar selanjutnya pada seri gambar berikut ini.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q60"},{"id":61,"section":"TIU","stem":"Carilah gambar selanjutnya pada seri gambar berikut ini.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q61"},{"id":62,"section":"TIU","stem":"Carilah gambar yang sesuai untuk melengkapi analogi gambar berikut.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q62"},{"id":63,"section":"TIU","stem":"Carilah gambar yang sesuai untuk melengkapi irama gambar berikut.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q63"},{"id":64,"section":"TIU","stem":"Carilah jaring-jaring kubus yang sesuai.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q64"},{"id":65,"section":"TIU","stem":"Carilah gambar yang sesuai untuk melengkapi irama gambar berikut.","options":{"A":"A","B":"B","C":"C","D":"D","E":"E"},"visual":"q65"},{"id":66,"section":"TKP","stem":"Anda bertugas di Dinas Kependudukan dan Pencatatan Sipil. Seorang warga datang mengeluhkan kesalahan tanggal lahir pada KTP elektroniknya yang mengakibatkan ia tidak dapat mendaftar program beasiswa. Batas pendaftaran beasiswa tinggal dua hari, sedangkan proses perubahan data memerlukan tahapan verifikasi. Warga tersebut meminta agar perubahan dilakukan saat itu juga karena khawatir kehilangan kesempatan. Sikap Anda adalah...","options":{"A":"Memeriksa keabsahan dokumen pendukung, membantu pengajuan perubahan data sesuai prosedur, dan memberikan bukti permohonan agar warga memiliki dokumen pendukung untuk menjelaskan kondisinya kepada penyelenggara beasiswa.","B":"Memastikan kelengkapan dokumen, mengajukan permohonan sesuai ketentuan, serta berkoordinasi dengan petugas berwenang mengenai kemungkinan penanganan lebih cepat tanpa mengabaikan proses verifikasi dan kepastian tindak lanjut.","C":"Memverifikasi kesesuaian dokumen, membantu memproses permohonan, serta mengarahkan warga untuk mengonfirmasi kemungkinan penggunaan bukti pengajuan sebagai persyaratan sementara kepada penyelenggara beasiswa.","D":"Memeriksa dokumen dan riwayat data kependudukan, berkonsultasi dengan petugas verifikasi mengenai estimasi penyelesaian, lalu membantu warga menentukan langkah pengajuan yang paling memungkinkan.","E":"Memastikan dokumen memenuhi persyaratan, membantu warga mengajukan koreksi melalui mekanisme resmi, serta memberikan akses pemantauan agar warga mengetahui perkembangan permohonannya."}},{"id":67,"section":"TKP","stem":"Anda bertugas di kantor pelayanan perizinan usaha. Seorang pelaku UMKM datang untuk mengurus izin usaha yang dibutuhkan sebagai persyaratan mengikuti program bantuan pemerintah. Namun, saat proses pengajuan berlangsung, sistem pelayanan daring mengalami gangguan sehingga permohonan tidak dapat diproses. Batas pendaftaran program bantuan berakhir pada hari tersebut. Warga meminta solusi karena seluruh dokumen persyaratan telah disiapkan. Sikap Anda adalah...","options":{"A":"Memastikan kelengkapan dokumen, menghubungi pengelola sistem untuk mengetahui perkiraan pemulihan, serta membantu menyiapkan pengajuan agar dapat segera diproses setelah layanan kembali tersedia.","B":"Memverifikasi dokumen persyaratan, berkonsultasi dengan penanggung jawab pelayanan mengenai alternatif pengajuan yang diizinkan, serta membantu warga menggunakan mekanisme tersebut apabila tersedia.","C":"Memeriksa kesiapan berkas, menyampaikan kendala kepada pengelola sistem, dan memberikan informasi resmi mengenai kondisi layanan beserta langkah yang perlu dipersiapkan warga.","D":"Memastikan kelengkapan persyaratan, mengoordinasikan penanganan gangguan dan kemungkinan prosedur alternatif yang sah, mendokumentasikan kendala, serta memastikan warga memperoleh kepastian tindak lanjut sesuai batas waktu yang dihadapi.","E":"Memverifikasi persyaratan administrasi, melaporkan gangguan kepada penanggung jawab layanan, serta membantu warga memperoleh informasi mengenai kemungkinan penyesuaian batas waktu dari penyelenggara program bantuan."}},{"id":68,"section":"TKP","stem":"Anda bertugas di kantor pelayanan perizinan. Seorang warga datang pukul 14.30 untuk mengajukan permohonan izin karena informasi pada situs resmi menyebutkan pelayanan berlangsung hingga pukul 15.00. Namun, petugas sebelumnya menyampaikan bahwa penerimaan berkas telah ditutup sejak pukul 14.00 untuk keperluan verifikasi harian. Warga merasa kecewa karena sudah menyesuaikan jadwal pekerjaannya berdasarkan informasi tersebut. Sikap Anda adalah...","options":{"A":"Memeriksa ketentuan jam pelayanan yang berlaku, mengonfirmasi kemungkinan penerimaan berkas kepada penanggung jawab, membantu warga memperoleh layanan melalui mekanisme yang diizinkan, serta mengupayakan perbaikan informasi yang berbeda.","B":"Menjelaskan perbedaan antara jam operasional kantor dan batas penerimaan berkas, kemudian membantu warga mempersiapkan dokumen agar pengajuan pada hari berikutnya dapat berlangsung lebih cepat.","C":"Memastikan ketentuan batas penerimaan berkas kepada koordinator, menyampaikan hasil klarifikasi kepada warga, serta menawarkan bantuan penjadwalan agar warga memperoleh kepastian waktu pelayanan.","D":"Mengonfirmasi informasi pada situs resmi kepada pengelola layanan, meminta pertimbangan penanggung jawab mengenai kemungkinan penerimaan berkas, dan menyampaikan keputusan tersebut secara terbuka kepada warga.","E":"Memeriksa kelengkapan persyaratan warga, mengarahkan penggunaan layanan pengajuan daring apabila tersedia, serta membantu memastikan seluruh dokumen siap diproses sesuai ketentuan."}},{"id":69,"section":"TKP","stem":"Anda bertugas di kantor pelayanan bantuan sosial daerah. Seorang warga lanjut usia datang untuk menyerahkan berkas pengajuan bantuan perbaikan rumah. Namun, surat keterangan penghasilan yang dibawanya dinyatakan tidak sesuai karena pemerintah daerah baru menerapkan format standar. Warga mengaku memperoleh format tersebut dari petugas kelurahan minggu lalu dan harus menempuh perjalanan cukup jauh untuk datang ke kantor pelayanan. Sementara itu, masa pengumpulan berkas akan segera berakhir. Sikap Anda adalah...","options":{"A":"Memastikan persyaratan terbaru, menghubungi pihak kelurahan untuk mengupayakan penyesuaian dokumen sesuai kewenangannya, serta membantu memastikan berkas warga dapat diproses sebelum batas pengumpulan apabila memenuhi ketentuan.","B":"Memeriksa kelengkapan berkas lainnya, memberikan contoh format yang benar, serta membantu warga menghubungi pihak kelurahan agar dokumen pengganti dapat disiapkan secepat mungkin.","C":"Mengklarifikasi perubahan format kepada petugas verifikasi, menjelaskan ketentuan terbaru kepada warga, kemudian meminta pertimbangan penanggung jawab mengenai kemungkinan penerimaan berkas sementara.","D":"Memastikan bahwa surat yang dibawa telah diterbitkan oleh kelurahan, kemudian berkoordinasi dengan bagian pelayanan agar warga memperoleh jadwal penyerahan dokumen pengganti yang sesuai.","E":"Menelusuri perbedaan format dokumen bersama petugas terkait, menjelaskan bagian yang harus disesuaikan, serta membantu warga memperoleh informasi mengenai mekanisme pengajuan yang masih tersedia."}},{"id":70,"section":"TKP","stem":"Anda bertugas sebagai petugas informasi di sebuah stasiun kereta api. Seorang anak berusia sekitar 7 tahun menghampiri Anda karena terpisah dari ibunya saat berpindah peron. Anak tersebut mengetahui nama ibunya, tetapi tidak mengingat nomor teleponnya. Sementara itu, kereta yang akan dinaiki anak tersebut dijadwalkan berangkat dalam 15 menit. Sikap Anda adalah...","options":{"A":"Meminta bantuan petugas peron untuk mencari ibu anak tersebut berdasarkan informasi perjalanan, sementara anak tetap berada di meja informasi dengan pendampingan petugas.","B":"Menghubungi petugas keamanan untuk menelusuri keberadaan orang tua melalui informasi tiket, kemudian memberikan perkembangan pencarian kepada anak agar tetap tenang.","C":"Membawa anak ke ruang pelayanan yang aman, berkoordinasi dengan petugas perjalanan untuk mengidentifikasi keberadaan ibunya, serta memastikan anak tetap didampingi sampai proses penjemputan selesai.","D":"Menenangkan anak, memastikan keselamatannya di area pelayanan, mengoordinasikan pencarian melalui petugas stasiun dan data perjalanan yang tersedia, serta memverifikasi identitas penjemput sebelum menyerahkan anak.","E":"Meminta petugas informasi menghubungi bagian perjalanan untuk memastikan kereta yang akan dinaiki, kemudian membantu mempertemukan anak dengan keluarganya melalui koordinasi petugas peron."}},{"id":71,"section":"TKP","stem":"Anda bertugas di pusat informasi sebuah tempat wisata yang sedang ramai pengunjung. Seorang anak berkebutuhan khusus ditemukan terpisah dari rombongan keluarganya. Anak tersebut terlihat gelisah, kesulitan menjawab pertanyaan, dan menutup telinganya ketika mendengar suara pengumuman dari pengeras suara. Petugas keamanan menawarkan bantuan untuk mencari keluarganya, sementara beberapa pengunjung mulai berkumpul karena penasaran. Sikap Anda adalah...","options":{"A":"Menjauhkan anak dari kerumunan, membawanya ke area yang lebih tenang, serta berkoordinasi dengan petugas keamanan untuk mencari keluarganya menggunakan informasi yang tersedia.","B":"Mengurangi rangsangan yang membuat anak tidak nyaman, menggunakan komunikasi sederhana sesuai responsnya, serta meminta petugas lain melakukan pencarian keluarga melalui jalur koordinasi internal.","C":"Mengarahkan anak ke ruang pelayanan yang lebih nyaman, meminta petugas pendamping membantu komunikasi, serta mencari informasi keluarga melalui tiket atau identitas yang dimilikinya.","D":"Menenangkan anak dengan pendekatan komunikasi yang sesuai, meminta pengunjung memberi ruang, serta menghubungi petugas terkait untuk memastikan pencarian keluarga dilakukan tanpa mengganggu kondisi anak.","E":"Membawa anak ke ruang pelayanan khusus, menghubungi petugas keamanan untuk menelusuri keberadaan rombongan, serta memastikan anak memperoleh pendampingan sampai keluarganya ditemukan."}},{"id":72,"section":"TKP","stem":"Anda bertugas di bagian pelayanan poliklinik sebuah rumah sakit. Seorang pasien lanjut usia bersama keluarganya mengeluh karena jadwal pemeriksaan dokter mundur hampir dua jam akibat dokter menangani kasus mendesak di unit lain. Berdasarkan pemeriksaan awal petugas medis, kondisi pasien masih stabil. Keluarga meminta agar pasien segera diperiksa karena sudah menunggu sejak pagi. Sikap Anda adalah...","options":{"A":"Menghubungi petugas poliklinik untuk memastikan perkiraan kedatangan dokter, menyampaikan kondisi antrean kepada keluarga, dan menawarkan tempat menunggu yang lebih nyaman bagi pasien.","B":"Berkoordinasi dengan bagian pelayanan untuk mengetahui kemungkinan pemeriksaan oleh dokter lain yang berwenang, kemudian menjelaskan pilihan layanan yang tersedia kepada keluarga pasien.","C":"Memastikan kondisi pasien melalui petugas medis, menjelaskan alasan perubahan jadwal, serta membantu keluarga memperoleh kepastian urutan pemeriksaan berdasarkan kondisi pelayanan saat itu.","D":"Meminta petugas medis melakukan penilaian ulang jika diperlukan, mengoordinasikan alternatif pelayanan yang memungkinkan, serta memberikan informasi perkembangan dan perkiraan waktu secara berkala kepada keluarga.","E":"Mendengarkan keluhan keluarga, mengonfirmasi perubahan jadwal kepada penanggung jawab poliklinik, serta membantu menyampaikan permintaan percepatan pemeriksaan melalui mekanisme pelayanan yang berlaku."}},{"id":73,"section":"TKP","stem":"Anda bertugas di kantor pelayanan administrasi kependudukan. Seorang warga datang mengurus akta kelahiran anaknya yang baru lahir. Namun, proses pengajuan terkendala karena status perkawinan orang tua pada Kartu Keluarga belum diperbarui, sedangkan warga telah membawa buku nikah resmi. Warga merasa keberatan apabila harus mengurus perubahan data secara terpisah karena telah mengambil izin kerja khusus untuk menyelesaikan administrasi anaknya. Sikap Anda adalah...","options":{"A":"Memeriksa kesesuaian buku nikah dengan identitas orang tua, menjelaskan keterkaitan pembaruan status perkawinan dengan penerbitan akta kelahiran, serta membantu warga menyiapkan persyaratan kedua layanan.","B":"Memverifikasi keabsahan dokumen perkawinan, mengonfirmasi ketentuan pencatatan kelahiran kepada petugas terkait, serta mengarahkan warga menggunakan mekanisme pelayanan yang paling sesuai dengan kondisi administrasinya.","C":"Mengidentifikasi data yang belum diperbarui, berkoordinasi dengan petugas pengelola Kartu Keluarga, serta mengupayakan agar permohonan pencatatan kelahiran dapat dipersiapkan selama proses pembaruan berlangsung.","D":"Memastikan dokumen perkawinan telah memenuhi persyaratan, membantu warga mengajukan perubahan status perkawinan, serta memberikan informasi mengenai tahapan penerbitan akta kelahiran setelah data disesuaikan.","E":"Memeriksa keabsahan dokumen dan ketentuan pencatatan yang berlaku, mengoordinasikan kemungkinan pelayanan terintegrasi sesuai prosedur, serta membantu penyelesaian administrasi tanpa mengharuskan warga mengulangi tahapan yang tidak diperlukan."}},{"id":74,"section":"TKP","stem":"Anda menjadi koordinator tim pengembangan sistem pelayanan digital yang melibatkan bagian administrasi, teknologi informasi, dan pelayanan masyarakat. Menjelang tahap uji coba, bagian administrasi belum menyerahkan seluruh data yang dibutuhkan karena sedang menjalani pemeriksaan internal. Tim teknologi informasi mengusulkan menggunakan data sementara agar jadwal tidak berubah, sedangkan bagian pelayanan mengkhawatirkan ketidaksesuaian informasi yang nantinya diterima masyarakat. Sikap Anda adalah...","options":{"A":"Mengupayakan percepatan penyediaan data melalui koordinasi dengan bagian administrasi, sambil meminta tim teknologi informasi melanjutkan pekerjaan yang tidak bergantung pada data tersebut.","B":"Mengadakan pembahasan dengan perwakilan setiap bagian untuk menentukan data yang telah terverifikasi, kemudian menyusun penyesuaian jadwal berdasarkan kesiapan masing-masing unit.","C":"Memfasilitasi koordinasi antarbagian untuk memetakan kebutuhan data, menyepakati penggunaan data yang telah tervalidasi, serta membagi tindak lanjut dan pengujian agar target tetap tercapai tanpa mengurangi keakuratan layanan.","D":"Meminta tim teknologi informasi menyiapkan lingkungan pengujian menggunakan data simulasi, sementara bagian administrasi menyelesaikan verifikasi sebelum sistem digunakan untuk pelayanan nyata.","E":"Menghubungi penanggung jawab masing-masing bagian untuk memperoleh kepastian penyelesaian, kemudian menyampaikan perkembangan dan kebutuhan penyesuaian kepada seluruh anggota tim."}},{"id":75,"section":"TKP","stem":"Anda tergabung dalam tim pengembangan aplikasi pelayanan masyarakat yang akan diluncurkan minggu depan. Salah satu anggota yang bertanggung jawab mengintegrasikan beberapa fitur mendapat penugasan mendadak untuk mengikuti pelatihan wajib selama tiga hari. Anggota tersebut telah menyelesaikan sebagian besar pekerjaannya dan menawarkan bantuan melalui komunikasi daring di luar jam pelatihan. Namun, beberapa anggota tim mengkhawatirkan keterlambatan karena proses integrasi membutuhkan koordinasi intensif. Sikap Anda adalah...","options":{"A":"Menyarankan anggota tersebut mendokumentasikan perkembangan pekerjaannya sebelum mengikuti pelatihan, kemudian meminta tim teknis melanjutkan integrasi berdasarkan dokumentasi yang tersedia.","B":"Mengusulkan penyesuaian jadwal pekerjaan teknis agar integrasi yang membutuhkan keterlibatan anggota tersebut dapat diselesaikan setelah pelatihan, sementara tugas lain tetap berjalan.","C":"Meminta anggota tersebut menentukan waktu komunikasi yang memungkinkan selama pelatihan, kemudian mengatur anggota lain untuk membantu penyelesaian fitur berdasarkan arahan yang diberikan.","D":"Memetakan pekerjaan yang belum selesai, mengatur serah terima pengetahuan kepada anggota yang kompeten, serta menyepakati pembagian tugas dan pengujian bersama agar integrasi tetap berjalan sesuai target.","E":"Mengajak tim teknis mengevaluasi pembagian tanggung jawab, menentukan fitur yang dapat diselesaikan secara paralel, serta menetapkan jadwal koordinasi dengan anggota yang mengikuti pelatihan."}},{"id":76,"section":"TKP","stem":"Anda menjadi koordinator tim survei lapangan yang sedang mengumpulkan data untuk evaluasi program pemerintah. Salah satu anggota baru belum terbiasa menggunakan aplikasi pendataan sehingga beberapa hasil surveinya tidak tersimpan dengan lengkap. Anggota tersebut aktif bertanya dan bersedia memperbaiki pekerjaannya, tetapi proses pendataan menjadi lebih lambat. Sementara itu, jumlah responden yang harus diselesaikan masih cukup banyak dan batas pengumpulan data semakin dekat. Sikap Anda adalah...","options":{"A":"Meminta anggota yang berpengalaman mendampingi proses pendataan pada beberapa responden awal, kemudian memberikan kesempatan anggota baru melanjutkan pekerjaan dengan pemeriksaan hasil secara berkala.","B":"Memetakan kendala penggunaan aplikasi, memasangkan anggota baru dengan pendamping yang kompeten, serta mengatur pembagian responden dan pemeriksaan data agar kualitas maupun target survei tetap terjaga.","C":"Mengadakan pengarahan ulang mengenai penggunaan aplikasi kepada seluruh anggota tim, kemudian meminta setiap anggota memastikan kelengkapan data sebelum meninggalkan lokasi survei.","D":"Menyesuaikan jumlah responden yang ditangani anggota baru, mengalihkan sebagian target kepada anggota lain, serta memberikan kesempatan memperbaiki hasil pendataan yang belum lengkap.","E":"Menyusun petunjuk teknis penggunaan aplikasi berdasarkan kendala yang ditemukan, kemudian meminta anggota baru mempraktikkannya sambil berkoordinasi dengan tim apabila mengalami kesulitan."}},{"id":77,"section":"TKP","stem":"Anda menjadi bagian dari tim penyelenggara program pemberdayaan masyarakat yang melibatkan beberapa instansi. Seorang anggota tim yang sebelumnya bertugas langsung di lapangan memiliki pemahaman mendalam mengenai karakteristik masyarakat sasaran. Namun, dalam rapat koordinasi, ia jarang menyampaikan pendapat karena diskusi lebih banyak didominasi perwakilan instansi yang memiliki jabatan lebih tinggi. Setelah rapat, ia menyampaikan kepada Anda bahwa beberapa rencana kegiatan kurang sesuai dengan kebutuhan masyarakat setempat. Sikap Anda adalah...","options":{"A":"Meminta anggota tersebut menuliskan hasil pengamatan dan rekomendasinya, kemudian membantu menyampaikan dokumen tersebut kepada koordinator agar menjadi bahan pertimbangan tim.","B":"Mengusulkan pertemuan kelompok kecil yang melibatkan anggota tersebut dan beberapa perwakilan instansi untuk membahas kondisi lapangan sebelum keputusan akhir ditetapkan.","C":"Mengajak anggota tersebut mengidentifikasi bagian rencana yang kurang sesuai, kemudian menyampaikan temuannya kepada koordinator agar dapat dibahas dalam rapat berikutnya.","D":"Mengusulkan agar rapat koordinasi berikutnya menyediakan sesi khusus bagi anggota yang memiliki pengalaman lapangan untuk menyampaikan masukan berdasarkan kondisi masyarakat.","E":"Mendiskusikan temuan anggota tersebut untuk memperkuat dasar rekomendasinya, membantunya mempersiapkan penyampaian, serta mengupayakan ruang diskusi yang setara agar ia dapat menjelaskan pandangannya secara langsung."}},{"id":78,"section":"TKP","stem":"Anda menjadi koordinator tim penyusunan rekomendasi kebijakan di sebuah instansi pemerintah. Salah satu anggota dikenal sangat teliti dan mampu menghasilkan analisis yang mendalam. Namun, ia lebih suka menyampaikan hasil pekerjaannya melalui laporan tertulis daripada berdiskusi langsung. Ketika rapat berlangsung, iajarang memberikan tanggapan meskipun memiliki data yang relevan. Akibatnya, beberapa keputusan tim kurang mempertimbangkan hasil analisis yang sebenarnya telah disiapkannya. Sikap Anda adalah...","options":{"A":"Memberikan tanggung jawab kepada anggota tersebut untuk menyusun analisis tertulis yang lebih terstruktur, sehingga seluruh anggota dapat memahami gagasannya sebelum mengambil keputusan.","B":"Mengajaknya mempersiapkan poin-poin analisis sebelum rapat, kemudian menyediakan kesempatan khusus baginya untuk menjelaskan temuan penting agar anggota lain memperoleh pemahaman yang sama.","C":"Menyesuaikan mekanisme rapat dengan meminta setiap anggota mengirimkan masukan tertulis sebelum diskusi, sehingga seluruh pandangan dapat dipertimbangkan dalam pengambilan keputusan.","D":"Mendiskusikan cara komunikasi yang paling nyaman baginya, membantu menyiapkan penyampaian temuan, serta melibatkannya secara bertahap dalam pembahasan agar kontribusinya dapat dipahami dan ditanggapi anggota lain.","E":"Membantu merangkum hasil analisisnya menjadi bahan diskusi yang mudah dipahami, kemudian menyampaikan inti temuannya kepada tim dengan tetap memberikan pengakuan atas kontribusi anggota tersebut."}},{"id":79,"section":"TKP","stem":"Anda menjadi koordinator program penyediaan air bersih di wilayah yang mengalami kekeringan. Pemerintah daerah hanya memiliki anggaran untuk membangun satu fasilitas penampungan air yang akan digunakan oleh tiga dusun. Dusun pertama mengusulkan lokasi di wilayahnya karena memiliki jumlah penduduk terbanyak, dusun kedua mengusulkan lokasi dekat sumber air, sedangkan dusun ketiga meminta prioritas karena sebagian besar warganya selama ini kesulitan memperoleh air bersih. Ketiga perwakilan dusun belum mencapai kesepakatan, sementara program harus segera dilaksanakan. Sikap Anda adalah...","options":{"A":"Memfasilitasi musyawarah ketiga dusun untuk menyepakati indikator kebutuhan, kelayakan teknis, dan kemudahan distribusi, kemudian menggunakan hasil kajian bersama sebagai dasar penentuan lokasi serta mekanisme pelayanan yang disepakati.","B":"Mengusulkan agar tim teknis menilai kondisi sumber air dan jaringan distribusi terlebih dahulu, kemudian menyampaikan rekomendasi lokasi kepada perwakilan dusun untuk mendapatkan tanggapan.","C":"Meminta masing-masing dusun menyampaikan data jumlah penduduk, tingkat kesulitan air bersih, dan kondisi wilayah, kemudian mengadakan pertemuan untuk membandingkan manfaat setiap usulan.","D":"Mengajak ketiga perwakilan dusun membahas kemungkinan pembangunan di lokasi yang paling mudah dijangkau, kemudian menyusun pembagian distribusi air agar seluruh wilayah memperoleh manfaat.","E":"Mengusulkan pembentukan tim kecil yang terdiri atas perwakilan tiap dusun untuk meninjau lokasi, mendokumentasikan temuan, dan menyampaikan rekomendasi bersama kepada pemerintah daerah."}},{"id":80,"section":"TKP","stem":"Anda bertugas di sebuah instansi pemerintah yang pernah bekerja sama dengan komunitas relawan kesehatan dalam program pemeriksaan gratis. Kerja sama tersebut telah berhenti selama tiga tahun karena perubahan prioritas kegiatan. Saat ini, instansi Anda akan menyelenggarakan program pemeriksaan kesehatan keliling yang membutuhkan dukungan relawan. Beberapa rekan menyarankan mencari mitra baru karena belum diketahui apakah komunitas tersebut masih aktif. Sikap Anda adalah...","options":{"A":"Menghubungi kembali pengurus komunitas untuk mengetahui perkembangan organisasinya, kemudian menyampaikan rencana kegiatan dan menawarkan kesempatan berkolaborasi sesuai kapasitas mereka.","B":"Menelusuri perkembangan komunitas melalui jaringan relawan yang masih aktif, kemudian meminta bantuan mereka mempertemukan tim dengan pengurus yang bertanggung jawab saat ini.","C":"Menghubungi pengurus komunitas secara langsung, mendiskusikan kebutuhan dan kemampuan masing-masing pihak, serta menyusun bentuk keterlibatan bersama berdasarkan kesepakatan.","D":"Mengirimkan undangan pertemuan resmi kepada komunitas beserta rancangan kegiatan, kemudian memberikan kesempatan kepada pengurus untuk menyampaikan bentuk dukungan yang memungkinkan.","E":"Mengajak komunitas tersebut bergabung dalam forum koordinasi bersama organisasi relawan lainnya, kemudian membahas pembagian kontribusi berdasarkan kesiapan setiap kelompok."}},{"id":81,"section":"TKP","stem":"Anda bertugas dalam program pelayanan administrasi kependudukan keliling di sebuah desa adat. Sebagian besar warga lanjut usia lebih memahami bahasa daerah daripada bahasa Indonesia. Tokoh adat setempat mengusulkan agar seluruh proses pelayanan dijelaskan melalui pertemuan bersama karena dianggap lebih sesuai dengan kebiasaan masyarakat. Namun, beberapa dokumen yang akan diperiksa memuat informasi pribadi warga yang harus dijaga kerahasiaannya. Sikap Anda adalah...","options":{"A":"Berkoordinasi dengan tokoh adat untuk menyampaikan informasi persyaratan melalui pertemuan bersama, kemudian mengatur pemeriksaan dokumen secara individual agar kerahasiaan warga terjaga.","B":"Menyiapkan panduan pelayanan dalam bahasa Indonesia dan bahasa daerah, kemudian melibatkan perangkat desa untuk membantu warga memahami prosedur sebelum melakukan pengajuan.","C":"Melibatkan tokoh adat dan pendamping bahasa dalam sosialisasi bersama, kemudian memisahkan proses verifikasi pribadi dengan tetap memastikan setiap warga memahami hak dan prosedur pelayanannya.","D":"Mengajak petugas yang memahami bahasa daerah mendampingi warga secara individual, sehingga penjelasan dapat diberikan secara langsung tanpa membuka informasi pribadi kepada masyarakat lain.","E":"Mendiskusikan mekanisme pelayanan dengan tokoh adat, kemudian menyediakan sesi konsultasi khusus bagi warga yang membutuhkan penjelasan tambahan sebelum dokumennya diperiksa."}},{"id":82,"section":"TKP","stem":"Anda menjadi anggota panitia festival budaya yang diselenggarakan oleh pemerintah daerah. Selama ini, acara lebih banyak menampilkan kesenian dari kelompok budaya mayoritas. Menjelang pelaksanaan, beberapa komunitas pendatang mengusulkan agar kesenian mereka juga ditampilkan karena telah lama menjadi bagian dari masyarakat setempat. Namun, waktu pertunjukan dan anggaran kegiatan sudah terbatas. Sebagian panitia khawatir perubahan susunan acara akan mengganggu persiapan yang hampir selesai. Sikap Anda adalah...","options":{"A":"Mengusulkan penambahan sesi pertunjukan singkat bagi komunitas pendatang dengan menyesuaikan durasi penampilan yang telah dijadwalkan sebelumnya.","B":"Mengajak perwakilan komunitas dan panitia meninjau susunan acara, menyepakati kriteria keterwakilan, serta menyesuaikan bentuk partisipasi agar keberagaman budaya terakomodasi secara proporsional.","C":"Membuka kesempatan bagi komunitas pendatang untuk berpartisipasi melalui pameran budaya, sehingga mereka tetap dapat memperkenalkan tradisinya tanpa mengubah jadwal pertunjukan utama.","D":"Memfasilitasi dialog dengan komunitas yang mengajukan usulan, kemudian mengupayakan kolaborasi penampilan yang dapat menggabungkan beberapa unsur budaya dalam waktu yang tersedia.","E":"Mengusulkan agar setiap komunitas diberikan kesempatan mengajukan penampilan melalui mekanisme seleksi terbuka, kemudian panitia menentukan peserta berdasarkan kesiapan dan kesesuaian acara."}},{"id":83,"section":"TKP","stem":"Anda menjadi koordinator pelayanan di posko pengungsian akibat bencana alam. Pengungsi berasal dari beberapa kelompok masyarakat dengan latar belakang budaya dan keyakinan berbeda. Sebagian pengungsi menyampaikan bahwa makanan yang disediakan tidak sesuai dengan aturan konsumsi yang mereka anut. Sementara itu, persediaan bahan makanan alternatif masih terbatas dan tim dapur harus segera menyiapkan makanan bagi ratusan pengungsi. Sikap Anda adalah...","options":{"A":"Mengidentifikasi kelompok pengungsi yang memiliki kebutuhan konsumsi khusus, kemudian meminta tim dapur menyesuaikan pembagian makanan berdasarkan ketersediaan bahan yang dapat digunakan.","B":"Berkoordinasi dengan perwakilan pengungsi untuk memahami kebutuhan konsumsi, kemudian menyampaikan hasilnya kepada tim logistik agar penyediaan bahan makanan berikutnya lebih sesuai.","C":"Meminta tim dapur menyediakan informasi komposisi makanan secara jelas, kemudian membantu pengungsi memilih hidangan yang sesuai dengan ketentuan konsumsi masing-masing.","D":"Mengupayakan penyediaan beberapa alternatif menu dari bahan yang tersedia, kemudian meminta perwakilan kelompok pengungsi membantu memberikan masukan mengenai kesesuaiannya.","E":"Mengonfirmasi kebutuhan konsumsi pengungsi tanpa membuat asumsi, memeriksa kesesuaian dan keamanan bahan bersama tim dapur, serta mengatur alternatif makanan yang memungkinkan tanpa mengurangi hak pelayanan kelompok lain."}},{"id":84,"section":"TKP","stem":"Anda bertugas dalam program pemeriksaan kesehatan gratis di sebuah desa. Sebagian warga lanjut usia menolak pemeriksaan tekanan darah secara rutin karena merasa cukup mengonsumsi ramuan herbal yang telah digunakan keluarga mereka selama bertahun-tahun. Mereka menganggap pemeriksaan medis hanya diperlukan ketika tubuh sudah menunjukkan keluhan. Sementara itu, kader kesehatan menemukan beberapa warga memiliki riwayat tekanan darah tinggi yang belum terpantau secara berkala. Sikap Anda adalah...","options":{"A":"Mengajak tokoh masyarakat dan kader kesehatan menyampaikan manfaat pemeriksaan tekanan darah, kemudian memberikan kesempatan kepada warga untuk berkonsultasi mengenai kebiasaan penggunaan ramuan herbal.","B":"Menyelenggarakan pemeriksaan tekanan darah dengan pendekatan yang lebih personal, menjelaskan manfaat pemantauan kesehatan, serta memberikan edukasi mengenai penggunaan herbal secara aman.","C":"Mendengarkan pandangan warga mengenai penggunaan ramuan, menjelaskan manfaat pemantauan tekanan darah tanpa menghakimi kebiasaan mereka, serta melibatkan tenaga medis dan kader untuk menyepakati pemeriksaan lanjutan yang sesuai.","D":"Berkoordinasi dengan tokoh masyarakat yang dipercaya untuk mengajak warga mengikuti pemeriksaan, kemudian menyediakan layanan konsultasi kesehatan yang mempertimbangkan kebiasaan pengobatan setempat.","E":"Mengidentifikasi alasan warga belum bersedia diperiksa, menyampaikan informasi mengenai risiko tekanan darah tinggi secara sederhana, serta menawarkan pemeriksaan secara bertahap sesuai kesediaan warga."}},{"id":85,"section":"TKP","stem":"Anda bertugas dalam program pendampingan kesehatan ibu dan bayi di sebuah desa. Sebagian masyarakat memiliki tradisi memberikan sedikit madu ke mulut bayi yang baru lahir sebagai simbol doa dan harapan agar anak tumbuh sehat. Tradisi tersebut telah diwariskan turun-temurun dan dianggap sebagai bagian penting dari penyambutan kelahiran. Namun, tenaga kesehatan menjelaskan bahwa pemberian madu kepada bayi di bawah satu tahun berisiko membahayakan kesehatannya. Beberapa keluarga keberatan apabila tradisi tersebut dihilangkan sepenuhnya. Sikap Anda adalah...","options":{"A":"Menjelaskan risiko pemberian madu kepada bayi berdasarkan informasi tenaga kesehatan, kemudian mengajak keluarga mempertimbangkan penyesuaian tradisi agar keselamatan bayi tetap terjaga.","B":"Mengajak tokoh masyarakat dan tenaga kesehatan membahas makna tradisi, kemudian menyusun pendekatan edukasi bersama agar keluarga dapat menyesuaikan pelaksanaannya secara aman.","C":"Mendengarkan pandangan keluarga mengenai makna tradisi, menjelaskan risiko kesehatan secara empatik, serta membantu menyepakati bentuk simbolis pengganti tanpa memberikan madu atau makanan lain kepada bayi.","D":"Mengadakan diskusi bersama keluarga dan kader kesehatan mengenai praktik perawatan bayi, kemudian memberikan kesempatan kepada masyarakat menentukan bentuk penyesuaian tradisi berdasarkan informasi yang diperoleh.","E":"Mengajak keluarga berkonsultasi dengan bidan sebelum melaksanakan tradisi, kemudian membantu menyampaikan rekomendasi kesehatan kepada tokoh masyarakat agar menjadi pertimbangan bersama."}},{"id":86,"section":"TKP","stem":"Anda bertugas dalam program pelayanan kesehatan ibu pascapersalinan. Seorang ibu yang baru melahirkan dua minggu lalu belum menjalani pemeriksaan lanjutan karena keluarganya memiliki tradisi bahwa ibu dan bayi tidak boleh meninggalkan rumah sebelum berusia 40 hari. Keluarga meyakini tradisi tersebut bertujuan menjaga keselamatan ibu dan bayi. Ibu tersebut bersedia menjalani pemeriksaan, tetapi tidak ingin menimbulkan perselisihan dengan keluarganya. Sikap Anda adalah...","options":{"A":"Menjelaskan kepada keluarga mengenai pentingnya pemeriksaan pascapersalinan, kemudian menawarkan penyesuaian jadwal atau metode pelayanan agar ibu tetap memperoleh pemantauan kesehatan.","B":"Berkoordinasi dengan bidan dan kader kesehatan untuk mengupayakan kunjungan rumah, kemudian memberikan informasi kepada keluarga mengenai pemeriksaan yang perlu dilakukan selama masa pemulihan.","C":"Mengajak ibu dan keluarganya membahas makna tradisi serta kebutuhan pemeriksaan, melibatkan tenaga kesehatan untuk menilai kondisi ibu, kemudian menyepakati mekanisme pelayanan yang aman dan sesuai kebutuhan tanpa menunda pemeriksaan yang diperlukan.","D":"Mengajak tokoh masyarakat dan kader kesehatan berdiskusi mengenai kebiasaan tersebut, kemudian menyampaikan alternatif pelayanan yang memungkinkan keluarga tetap menjalankan tradisinya.","E":"Menanyakan kondisi dan kendala yang dialami ibu, memberikan penjelasan mengenai manfaat pemeriksaan lanjutan, serta membantu keluarga menghubungi petugas kesehatan untuk memperoleh arahan pelayanan."}},{"id":87,"section":"TKP","stem":"Anda menjadi wali kelas yang sedang mempersiapkan kegiatan kemah pembentukan karakter bagi siswa. Kegiatan tersebut dirancang untuk melatih kemandirian, toleransi, dan kerja sama melalui aktivitas kelompok selama dua hari satu malam. Beberapa orang tua menyampaikan keberatan karena kebiasaan keluarga mereka tidak memperbolehkan anak menginap di luar rumah tanpa pendamping keluarga. Mereka mendukung tujuan kegiatan, tetapi menginginkan anak tetap pulang pada malam hari. Sementara itu, sejumlah aktivitas kelompok telah dirancang untuk dilaksanakan pada malam hari. Sikap Anda adalah...","options":{"A":"Mengadakan pertemuan dengan orang tua untuk menjelaskan pengawasan dan keamanan kegiatan, kemudian meminta mereka mempertimbangkan kembali keikutsertaan anak dalam seluruh rangkaian acara.","B":"Mengajak orang tua membahas kekhawatiran mereka, kemudian memberikan pilihan kegiatan siang hari dan tugas pengganti untuk aktivitas malam tanpa mengubah ketentuan bagi siswa lainnya.","C":"Meminta panitia mengevaluasi kegiatan yang mengharuskan siswa menginap, kemudian mengupayakan alternatif aktivitas agar tujuan pembentukan karakter tetap dapat dicapai melalui bentuk partisipasi yang berbeda.","D":"Menjelaskan manfaat kegiatan menginap bagi pengembangan karakter, kemudian berkoordinasi dengan orang tua untuk menentukan bentuk pendampingan yang dapat meningkatkan rasa aman.","E":"Mendiskusikan kebutuhan keluarga dan tujuan kegiatan bersama panitia serta orang tua, kemudian menyusun alternatif partisipasi yang setara agar siswa tetap memperoleh pengalaman kerja sama tanpa harus mengabaikan nilai keluarganya."}},{"id":88,"section":"TKP","stem":"Anda menjadi administrator penyimpanan dokumen digital di sebuah instansi pemerintah. Seluruh dokumen laporan kegiatan disimpan dalam folder cloud yang dapat diakses oleh anggota tim. Menjelang pemeriksaan internal, seorang anggota menemukan bahwa beberapa dokumen penting pernah mengalami perubahan tanpa diketahui siapa yang melakukannya. Setelah diperiksa, ternyata seluruh anggota memiliki akses pengeditan yang sama. Pimpinan meminta agar sistem penyimpanan diperbaiki tanpa menghambat kerja sama tim. Sikap Anda adalah...","options":{"A":"Mengaktifkan pencatatan aktivitas pengguna, menyusun pembagian hak akses berdasarkan tanggung jawab, serta menerapkan prosedur persetujuan untuk perubahan dokumen yang telah ditetapkan sebagai dokumen resmi.","B":"Membatasi akses pengeditan kepada koordinator setiap unit, kemudian meminta anggota lain mengajukan permohonan apabila membutuhkan perubahan dokumen.","C":"Memisahkan folder dokumen yang telah disahkan dari folder kerja bersama, lalu memberikan hak pengeditan kepada petugas yang bertanggung jawab atas masing-masing dokumen.","D":"Mengaktifkan fitur riwayat versi dan pemulihan dokumen, kemudian meminta setiap anggota menggunakan identitas akun masing-masing agar aktivitas perubahan dapat ditelusuri.","E":"Melakukan pemeriksaan terhadap dokumen yang mengalami perubahan, menyimpan salinan cadangan, serta menetapkan jadwal evaluasi akses secara berkala bersama penanggung jawab unit."}},{"id":89,"section":"TKP","stem":"Anda bertugas mengelola folder digital untuk kegiatan pelatihan masyarakat yang melibatkan mitra eksternal. Agar pekerjaan lebih cepat, salah satu anggota tim membagikan tautan folder kepada mitra dengan izin pengeditan. Namun, folder tersebut juga berisi data pribadi peserta yang sebenarnya tidak diperlukan oleh mitra. Anda mengetahui bahwa tautan tersebut dapat diteruskan kepada pihak lain, sementara proses kerja sama masih berlangsung. Sikap Anda adalah...","options":{"A":"Mengatur ulang izin folder agar hanya akun mitra yang terdaftar dapat mengaksesnya, kemudian mengingatkan anggota tim mengenai pentingnya menjaga kerahasiaan data peserta.","B":"Memindahkan dokumen yang memuat data pribadi ke lokasi penyimpanan internal, kemudian meminta mitra menggunakan folder bersama hanya untuk keperluan koordinasi kegiatan.","C":"Membuat folder khusus berisi dokumen yang diperlukan mitra, memberikan hak akses sesuai tugasnya, serta menetapkan batas waktu penggunaan agar dokumen tidak dapat diakses setelah kerja sama berakhir.","D":"Memeriksa riwayat akses, menonaktifkan tautan yang terlalu terbuka, memisahkan dokumen berdasarkan tingkat kerahasiaan, serta memberikan akses terbatas sesuai kebutuhan mitra.","E":"Menghubungi mitra untuk menjelaskan batas penggunaan dokumen, menyepakati aturan kerahasiaan data, serta meminta anggota tim melakukan pemeriksaan terhadap dokumen yang dibagikan."}},{"id":90,"section":"TKP","stem":"Anda menjadi administrator dokumen digital pada sebuah instansi yang menggunakan penyimpanan cloud untuk kerja sama antarunit. Menjelang pengumpulan laporan bulanan, seorang pegawai tidak sengaja menghapus beberapa folder penting saat melakukan sinkronisasi dari komputernya. Penghapusan tersebut ternyata ikut tersinkronisasi ke folder bersama sehingga dokumen tidak lagi terlihat oleh anggota lain. Sistem memiliki fitur pemulihan versi, tetapi beberapa anggota sudah mulai mengunggah ulang dokumen dari salinan masing-masing. Sikap Anda adalah...","options":{"A":"Menghentikan sementara perubahan pada folder terdampak, memeriksa riwayat aktivitas, memulihkan dokumen dari versi yang terverifikasi, serta menata kembali hak akses dan prosedur pencadangan agar kejadian serupa tidak terulang.","B":"Mengidentifikasi dokumen yang terhapus melalui riwayat sistem, meminta setiap unit memeriksa salinan yang tersedia, kemudian menyusun kembali dokumen berdasarkan versi terbaru yang telah dikonfirmasi.","C":"Menggunakan fitur pemulihan cloud untuk mengembalikan dokumen yang terhapus, kemudian meminta setiap anggota melakukan pemeriksaan terhadap hasil pemulihan sebelum laporan dikumpulkan.","D":"Berkoordinasi dengan penanggung jawab setiap unit untuk memastikan versi dokumen yang benar, mengatur penghentian unggahan ganda, kemudian melakukan pemulihan berdasarkan catatan aktivitas sistem.","E":"Meminta anggota menghentikan pengunggahan ulang, menyimpan salinan dokumen yang masih tersedia, serta menghubungi pengelola sistem untuk menentukan metode pemulihan yang paling aman."}},{"id":91,"section":"TKP","stem":"Anda bertugas mengelola dokumen standar operasional prosedur (SOP) pelayanan pada sebuah instansi pemerintah. Beberapa unit kerja menyimpan salinan SOP dengan nama dan tanggal pembaruan berbeda. Salah satu dokumen memiliki tanggal paling baru, tetapi belum memperoleh pengesahan pimpinan, sedangkan dokumen lainnya sudah disahkan namun memiliki tanggal penyimpanan lebih lama. Akibatnya, pegawai mulai menggunakan prosedur yang berbeda dalam memberikan pelayanan. Sikap Anda adalah...","options":{"A":"Mengelompokkan seluruh dokumen berdasarkan tanggal pembaruan, kemudian meminta setiap unit memeriksa kembali kesesuaian SOP sebelum digunakan dalam pelayanan.","B":"Menghubungi penanggung jawab penyusunan SOP untuk memastikan dokumen yang berlaku, kemudian menyampaikan hasil klarifikasi kepada seluruh unit agar menggunakan acuan yang sama.","C":"Membandingkan substansi setiap versi dokumen, mengidentifikasi perbedaan yang ditemukan, serta meminta unit terkait menyepakati prosedur yang paling sesuai dengan kebutuhan pelayanan.","D":"Memverifikasi status pengesahan setiap dokumen, menetapkan versi yang sah sebagai acuan bersama, serta mengarsipkan versi sebelumnya dengan penamaan dan riwayat perubahan yang jelas.","E":"Menyusun daftar seluruh versi SOP beserta tanggal dan penanggung jawabnya, kemudian menyediakan folder khusus agar pegawai dapat membedakan dokumen yang masih dalam pembahasan dan yang telah diterbitkan."}},{"id":92,"section":"TKP","stem":"Anda menjadi koordinator penyusunan laporan kinerja tahunan yang melibatkan beberapa bidang. Setiap bidang telah menyerahkan laporan melalui penyimpanan cloud, tetapi sebagian anggota juga mengirimkan revisi melalui email. Akibatnya, terdapat beberapa dokumen dengan nama hampir sama dan isi yang sedikit berbeda. Salah satu anggota mengusulkan menggunakan file dengan tanggal modifikasi paling baru, sementara anggota lain menganggap versi yang tersimpan di cloud sebagai dokumen utama. Sikap Anda adalah...","options":{"A":"Menetapkan penyimpanan cloud sebagai sumber dokumen utama, kemudian meminta setiap bidang memeriksa apakah revisi yang pernah dikirim melalui email sudah tercantum dalam versi tersebut.","B":"Membandingkan seluruh revisi dengan catatan persetujuan masing-masing bidang, menetapkan versi terverifikasi sebagai acuan, serta menerapkan mekanisme pembaruan dan penamaan dokumen yang disepakati bersama.","C":"Mengumpulkan dokumen dari seluruh bidang berdasarkan tanggal pengiriman, kemudian meminta setiap penanggung jawab memilih versi yang paling lengkap untuk digabungkan menjadi laporan akhir.","D":"Mengadakan koordinasi dengan seluruh penanggung jawab bidang untuk menentukan dokumen yang akan digunakan, kemudian meminta setiap bidang menyampaikan konfirmasi tertulis atas versi pilihannya.","E":"Menyusun daftar perubahan dari dokumen email dan cloud, kemudian menggabungkan bagian yang telah memperoleh persetujuan agar tidak ada hasil revisi yang terlewatkan."}},{"id":93,"section":"TKP","stem":"Anda bertugas mengolah laporan kunjungan pasien dari beberapa puskesmas untuk evaluasi pelayanan kesehatan daerah. Setiap puskesmas mengirimkan data menggunakan format tanggal yang berbeda. Sebagian menggunakan urutan hari-bulan-tahun, sedangkan lainnya menggunakan bulan-hari-tahun. Setelah data digabungkan, sistem menampilkan lonjakan jumlah kunjungan pada bulan tertentu yang tidak sesuai dengan laporan masing-masing puskesmas. Pimpinan meminta hasil evaluasi segera disiapkan untuk rapat. Sikap Anda adalah...","options":{"A":"Memisahkan data berdasarkan puskesmas asal, menyesuaikan format tanggal setiap sumber, kemudian membandingkan hasil penggabungan dengan laporan kunjungan yang telah disampaikan sebelumnya.","B":"Mengidentifikasi tanggal yang berpotensi tertukar, mengonfirmasi format kepada operator puskesmas, kemudian melakukan koreksi sebelum menyusun grafik perkembangan kunjungan.","C":"Menggunakan pengaturan regional yang sesuai untuk setiap berkas, kemudian melakukan pemeriksaan terhadap distribusi kunjungan agar perubahan format tidak menggeser periode laporan.","D":"Memeriksa data yang menyebabkan lonjakan, membandingkan jumlah kunjungan dengan laporan sumber, serta meminta klarifikasi terhadap catatan yang menunjukkan perbedaan signifikan.","E":"Menelusuri format tanggal setiap sumber, menetapkan standar tanggal yang konsisten, memverifikasi entri ambigu kepada puskesmas terkait, serta mencocokkan kembali hasil agregasi sebelum laporan disampaikan."}},{"id":94,"section":"TKP","stem":"Anda menjadi pengelola aplikasi pendaftaran beasiswa pemerintah daerah. Sistem secara otomatis menandai beberapa pendaftar sebagai data ganda karena menggunakan alamat rumah dan nomor telepon yang sama. Setelah ditelusuri, ternyata sebagian pendaftar merupakan saudara kandung yang sama-sama memenuhi persyaratan dan menggunakan nomor telepon orang tua untuk pendaftaran. Panitia mengusulkan agar seluruh data yang terdeteksi ganda diperiksa secara manual, sedangkan jadwal seleksi semakin dekat. Sikap Anda adalah...","options":{"A":"Memeriksa pola kesamaan data, memverifikasi identitas setiap pendaftar melalui dokumen resmi, memperbaiki status yang keliru, serta mengevaluasi aturan deteksi agar penggunaan kontak keluarga tidak otomatis dianggap duplikasi.","B":"Mengidentifikasi pendaftar yang memiliki kontak sama, kemudian meminta mereka mengonfirmasi identitas secara terpisah agar proses seleksi tetap dapat dilanjutkan berdasarkan data masing-masing.","C":"Mengusulkan penyesuaian parameter pendeteksian dengan mengutamakan identitas unik pendaftar, kemudian meminta panitia melakukan pemeriksaan terhadap data yang menunjukkan ketidaksesuaian.","D":"Memisahkan data yang terindikasi ganda untuk pemeriksaan khusus, kemudian memastikan peserta yang terbukti berbeda tetap memperoleh kesempatan mengikuti seleksi sesuai ketentuan.","E":"Membandingkan identitas dan dokumen pendaftar yang terdeteksi ganda, kemudian berkoordinasi dengan tim teknis untuk memperbaiki klasifikasi sebelum hasil seleksi ditetapkan."}},{"id":95,"section":"TKP","stem":"Anda bertugas mengelola aplikasi pengajuan penggantian biaya perjalanan dinas di sebuah instansi pemerintah. Setelah sistem digunakan selama satu bulan, banyak pegawai mengunggah bukti pembayaran pada kolom yang tidak sesuai. Setelah diperiksa, beberapa kolom memiliki nama yang hampir sama dan petunjuk penggunaannya kurang spesifik. Akibatnya, petugas keuangan harus berulang kali mengembalikan pengajuan untuk diperbaiki. Sikap Anda adalah...","options":{"A":"Menyusun panduan visual yang menjelaskan fungsi setiap kolom, kemudian mengadakan pendampingan singkat agar pegawai lebih memahami prosedur pengajuan.","B":"Mengidentifikasi jenis kesalahan yang paling sering muncul, berkoordinasi dengan pengelola aplikasi untuk memperjelas petunjuk, serta memeriksa efektivitas perubahan melalui beberapa pengajuan berikutnya.","C":"Menyediakan layanan konsultasi bagi pegawai yang mengalami kesulitan, kemudian membantu mereka memperbaiki dokumen sebelum pengajuan diteruskan kepada bagian keuangan.","D":"Menganalisis pola kesalahan dan pengalaman pengguna, mengoordinasikan perbaikan label serta validasi unggahan, kemudian menguji perubahan sebelum diterapkan kepada seluruh pegawai.","E":"Menambahkan contoh dokumen yang benar pada halaman bantuan aplikasi, kemudian membuka saluran komunikasi agar pegawai dapat memperoleh penjelasan ketika menemukan kendala."}},{"id":96,"section":"TKP","stem":"Anda bertanggung jawab menyelesaikan laporan penggunaan anggaran yang harus diserahkan kepada bagian keuangan sebelum pukul 15.00. Ketika proses pemeriksaan akhir hampir selesai, pimpinan meminta Anda mendampingi kunjungan tim evaluasi dari instansi lain yang dijadwalkan berlangsung pada waktu bersamaan. Pimpinan menilai kehadiran Anda penting karena memahami pelaksanaan program, sedangkan laporan anggaran juga diperlukan untuk proses pencairan tahap berikutnya. Sikap Anda adalah...","options":{"A":"Menjelaskan perkembangan laporan kepada pimpinan, mengusulkan penyesuaian pembagian tugas, serta meminta arahan mengenai prioritas agar kedua kepentingan dapat ditangani sesuai kebutuhan organisasi.","B":"Menyelesaikan pemeriksaan laporan terlebih dahulu, kemudian bergabung dalam kunjungan evaluasi setelah memastikan dokumen diserahkan sesuai batas waktu yang ditentukan.","C":"Menyiapkan ringkasan informasi program untuk tim evaluasi, kemudian berkoordinasi dengan rekan yang memahami kegiatan agar dapat mendampingi kunjungan sementara Anda menyelesaikan laporan.","D":"Menginformasikan kondisi kedua pekerjaan kepada pimpinan, kemudian menawarkan penyelesaian laporan melalui pembagian tugas dengan bagian keuangan agar Anda dapat mengikuti kunjungan evaluasi.","E":"Mengidentifikasi bagian pekerjaan yang masih perlu diselesaikan, kemudian menyusun alternatif pengaturan waktu untuk dibahas dengan pimpinan sebelum menjalankan kedua tanggung jawab tersebut."}},{"id":97,"section":"TKP","stem":"Anda bertugas di bagian administrasi sebuah instansi pemerintah. Saat sedang menyelesaikan dokumen pertanggungjawaban kegiatan yang dijadwalkan diperiksa hari ini, Anda diminta membantu tim lain menyiapkan data untuk rapat mendadak bersama pimpinan. Ketua tim tersebut menyampaikan bahwa data dibutuhkan secepatnya, tetapi Anda belum mengetahui apakah rapat itu lebih mendesak daripada pemeriksaan dokumen yang sedang dikerjakan. Kedua pekerjaan membutuhkan ketelitian dan tidak dapat diselesaikan secara bersamaan. Sikap Anda adalah...","options":{"A":"Menyampaikan perkembangan pekerjaan kepada ketua tim yang meminta bantuan, kemudian menawarkan waktu pengerjaan setelah dokumen pertanggungjawaban selesai diperiksa.","B":"Mengidentifikasi sisa pekerjaan dan memperkirakan waktu penyelesaian masing-masing tugas, kemudian membagi waktu agar kedua pekerjaan tetap dapat ditangani sesuai jadwal.","C":"Menghubungi atasan untuk mengklarifikasi urgensi kedua pekerjaan, menjelaskan konsekuensi terhadap tenggat masing-masing, serta menyepakati prioritas dan pembagian tugas yang paling sesuai.","D":"Meminta rekan yang memahami dokumen pertanggungjawaban membantu pemeriksaan akhir, sehingga Anda dapat segera menangani permintaan data dari tim lain.","E":"Berkoordinasi dengan kedua tim mengenai kebutuhan dan batas waktu pekerjaan, kemudian mengusulkan pengaturan penyelesaian yang memungkinkan sebelum meminta persetujuan atasan."}},{"id":98,"section":"TKP","stem":"Anda menjadi penanggung jawab pengelolaan pengaduan masyarakat di sebuah instansi pemerintah. Hari ini merupakan batas akhir penyampaian tanggapan resmi atas beberapa pengaduan yang telah diverifikasi. Ketika Anda sedang menyiapkan dokumen tanggapan, atasan meminta Anda membantu tim evaluasi menyusun bahan untuk pertemuan dengan pejabat kementerian yang dijadwalkan berlangsung besok pagi. Atasan belum menjelaskan apakah bahan evaluasi tersebut harus selesai hari ini, sementara kedua pekerjaan sama-sama membutuhkan pemeriksaan yang cermat. Sikap Anda adalah...","options":{"A":"Menyiapkan bagian tanggapan pengaduan yang paling mendesak terlebih dahulu, kemudian meminta rekan membantu mengumpulkan informasi yang diperlukan untuk bahan evaluasi.","B":"Mengonfirmasi kebutuhan bahan evaluasi kepada tim terkait, kemudian menyusun jadwal pengerjaan agar kedua dokumen dapat diperiksa sebelum diserahkan.","C":"Berkoordinasi dengan rekan yang memahami pengelolaan pengaduan untuk membantu pemeriksaan dokumen, sementara Anda mulai menyiapkan bahan evaluasi sesuai permintaan atasan.","D":"Menjelaskan tenggat pengaduan dan kebutuhan waktu penyelesaiannya kepada atasan, mengklarifikasi prioritas bahan evaluasi, serta menyepakati pembagian pekerjaan dan pemeriksaan akhir sesuai arahan.","E":"Menyampaikan kondisi kedua pekerjaan kepada atasan, menawarkan beberapa alternatif pengaturan waktu, kemudian menyesuaikan pelaksanaan berdasarkan prioritas yang ditetapkan."}},{"id":99,"section":"TKP","stem":"Anda menjadi koordinator kegiatan pelatihan pegawai baru yang telah dijadwalkan sejak dua minggu sebelumnya. Pada hari pelaksanaan, pimpinan meminta Anda menghadiri rapat evaluasi mendadak bersama tim pemeriksa dari kementerian yang tidak dapat dijadwalkan ulang. Anda telah menyiapkan seluruh materi pelatihan, sementara dua anggota tim memiliki pengalaman menyampaikan materi yang sama, tetapi belum pernah menjadi penanggung jawab utama. Sikap Anda adalah...","options":{"A":"Berkoordinasi dengan anggota tim untuk membagi sesi pelatihan sesuai keahlian masing-masing, kemudian meminta mereka menyampaikan perkembangan kegiatan selama Anda mengikuti rapat.","B":"Menunjuk anggota yang paling menguasai materi untuk memimpin pelatihan, memberikan arahan mengenai tujuan dan alur kegiatan, serta memastikan mekanisme evaluasi dan pelaporan tetap berjalan.","C":"Menyampaikan kondisi kepada pimpinan, kemudian mengusulkan penyesuaian waktu pelatihan agar Anda tetap dapat memberikan pengarahan utama sebelum mengikuti rapat.","D":"Meminta anggota tim melanjutkan pelatihan berdasarkan materi yang telah disiapkan, kemudian melakukan evaluasi bersama setelah rapat untuk memastikan tujuan pembelajaran tercapai.","E":"Mengadakan koordinasi singkat dengan tim pelatihan, menyepakati pembagian peran sementara, serta menyiapkan panduan pelaksanaan agar kegiatan dapat berlangsung meskipun Anda tidak hadir secara langsung."}},{"id":100,"section":"TKP","stem":"Anda menjadi koordinator tim penyusunan laporan kinerja yang akan dipresentasikan dalam rapat evaluasi internal. Anda dijadwalkan memimpin pembahasan hasil laporan bersama seluruh anggota pada sore hari. Namun, pada waktu yang hampir bersamaan, pimpinan meminta Anda menghadiri pertemuan penting dengan pihak pengawas eksternal untuk memberikan klarifikasi mengenai pelaksanaan program. Rapat internal diperlukan agar laporan segera disahkan, sementara dua anggota tim telah menguasai substansi laporan dan memahami catatan perbaikannya. Sikap Anda adalah...","options":{"A":"Mengonfirmasi kebutuhan kehadiran dalam pertemuan eksternal, mendelegasikan kepemimpinan rapat internal kepada anggota kompeten dengan batas kewenangan yang jelas, serta memastikan hasil pembahasan diverifikasi sebelum pengesahan.","B":"Meminta anggota yang memahami laporan memimpin rapat internal, kemudian memberikan kesempatan kepada seluruh peserta menyepakati hasil akhir berdasarkan data yang telah tersedia.","C":"Menghadiri pertemuan eksternal sesuai arahan pimpinan, kemudian meminta tim menyusun catatan pembahasan internal untuk diperiksa dan ditindaklanjuti setelah Anda kembali.","D":"Berkoordinasi dengan pimpinan mengenai benturan jadwal, kemudian mengusulkan agar rapat internal dilanjutkan oleh anggota yang memahami substansi dan hasilnya disampaikan melalui laporan tertulis.","E":"Membagi tanggung jawab pembahasan laporan kepada dua anggota yang kompeten, kemudian memberikan arahan mengenai bagian yang harus diselesaikan sebelum Anda menghadiri pertemuan eksternal."}},{"id":101,"section":"TKP","stem":"Anda menjadi penanggung jawab kegiatan simulasi pelayanan terpadu yang melibatkan beberapa unit kerja. Seluruh perlengkapan telah disiapkan dan setiap unit telah mengirimkan perwakilannya. Namun, sesaat sebelum simulasi dimulai, pimpinan meminta Anda menghadiri pertemuan mendadak dengan instansi pengawas untuk menjelaskan hasil evaluasi program sebelumnya. Pertemuan tersebut tidak dapat diwakilkan karena Anda merupakan penanggung jawab utama laporan evaluasi. Sementara itu, dua anggota tim telah memahami skenario simulasi dan mampu mengoordinasikan peserta. Sikap Anda adalah...","options":{"A":"Membagi tanggung jawab pelaksanaan kepada anggota yang kompeten, memastikan alur dan indikator simulasi dipahami, serta menyepakati mekanisme pelaporan agar kegiatan tetap berjalan selama Anda menghadiri pertemuan.","B":"Menunjuk anggota yang paling berpengalaman sebagai pengarah simulasi, kemudian meminta seluruh unit mengikuti skenario yang sudah ditetapkan dan menyampaikan hasilnya setelah kegiatan selesai.","C":"Meminta anggota tim melaksanakan tahapan awal simulasi, kemudian menjadwalkan evaluasi dan pengambilan keputusan akhir setelah Anda menyelesaikan pertemuan.","D":"Mengadakan koordinasi singkat dengan seluruh perwakilan unit, menjelaskan kondisi perubahan penugasan, serta meminta masing-masing unit melaksanakan bagian simulasi sesuai tanggung jawabnya.","E":"Mengusulkan kepada pimpinan agar simulasi dipimpin oleh anggota tim lain, kemudian menyiapkan dokumen pelaksanaan dan catatan teknis yang diperlukan sebagai panduan kegiatan."}},{"id":102,"section":"TKP","stem":"Anda menjadi koordinator tim verifikasi data penerima bantuan yang harus menyelesaikan laporan pada sore hari. Ketika proses pemeriksaan berlangsung, Anda mendapat kabar bahwa orang tua Anda perlu menjalani pemeriksaan lanjutan di rumah sakit lebih awal dari jadwal. Kondisinya masih stabil dan saudara Anda bersedia mendampingi, tetapi keluarga berharap Andajuga dapat hadir. Sementara itu, tim membutuhkan arahan Anda untuk menyelesaikan beberapa data yang belum sesuai. Sikap Anda adalah...","options":{"A":"Memastikan saudara dapat mendampingi orang tua selama pemeriksaan, kemudian melanjutkan koordinasi tim sambil memantau perkembangan kondisi keluarga secara berkala.","B":"Mengatur pembagian pekerjaan kepada anggota yang kompeten, kemudian mendampingi orang tua agar kebutuhan keluarga terpenuhi tanpa menghambat penyelesaian laporan.","C":"Mengomunikasikan kondisi keluarga kepada atasan, kemudian mengusulkan penyesuaian waktu kerja agar Anda dapat menghadiri sebagian pemeriksaan dan tetap menyelesaikan tanggung jawab tim.","D":"Memastikan orang tua memperoleh pendampingan yang memadai, mengoordinasikan penyelesaian tugas bersama anggota tim, serta menyiapkan penyesuaian tanggung jawab apabila kondisi keluarga membutuhkan kehadiran Anda.","E":"Mendiskusikan kebutuhan pendampingan dengan keluarga, kemudian meminta anggota senior membantu mengawasi proses verifikasi agar Anda dapat lebih fleksibel membagi waktu."}},{"id":103,"section":"TKP","stem":"Anda menjadi anggota komunitas pemuda yang sedang mempersiapkan kegiatan edukasi sejarah daerah. Salah satu panitia membuat video pendek mengenai konflik sosial yang pernah terjadi di wilayah tersebut. Video menggunakan potongan wawancara seorang tokoh sejarah yang menyebutkan keterlibatan kelompok masyarakat tertentu. Namun, setelah Anda menonton rekaman lengkapnya, ternyata terdapat bagian penjelasan yang tidak dimasukkan sehingga makna pernyataan tokoh tersebut menjadi berbeda. Video sudah dijadwalkan untuk dipublikasikan melalui media sosial komunitas. Sikap Anda adalah...","options":{"A":"Mengusulkan agar video dilengkapi dengan bagian wawancara yang sebelumnya terpotong, kemudian meminta panitia memeriksa kembali kesesuaian narasi sebelum dipublikasikan.","B":"Menyarankan agar video diganti dengan konten yang lebih menonjolkan persatuan masyarakat, kemudian mengajak panitia mengevaluasi pemilihan materi sejarah untuk publikasi berikutnya.","C":"Mengajak panitia mendiskusikan perbedaan makna antara video pendek dan rekaman lengkap, kemudian menyarankan penyajian beberapa sudut pandang agar penonton memperoleh informasi yang lebih luas.","D":"Memeriksa rekaman asli dan konteks pernyataan dengan sumber sejarah yang kredibel, mengajak panitia memperbaiki narasi yang menyesatkan, serta memastikan video yang dipublikasikan tidak menimbulkan prasangka terhadap kelompok masyarakat.","E":"Meminta tim penyuntingan meninjau kembali video bersama narasumber atau pihak yang memahami sejarah, kemudian menambahkan penjelasan konteks agar isi video tidak menimbulkan kesalahpahaman."}},{"id":104,"section":"TKP","stem":"Anda menjadi anggota panitia kegiatan kebudayaan yang melibatkan masyarakat dari berbagai latar belakang. Dalam rapat persiapan, seorang tokoh masyarakat menceritakan pengalaman keluarganya yang pernah mengalami konflik dengan kelompok pendatang puluhan tahun lalu. Berdasarkan cerita tersebut, ia mengusulkan agar kelompok pendatang tidak diberikan tanggung jawab penting dalam kepanitiaan karena dianggap sulit dipercaya. Beberapa anggota mulai menyetujui usulan tersebut sebagai bentuk penghormatan terhadap pengalaman tokoh masyarakat. Sikap Anda adalah...","options":{"A":"Menghargai pengalaman tokoh masyarakat, kemudian mengusulkan agar pembagian tanggung jawab didasarkan pada kemampuan dan rekam jejak masing-masing anggota, bukan latar belakang kelompoknya.","B":"Mengajak peserta mendengarkan pengalaman dari kelompok masyarakat lain, sehingga keputusan kepanitiaan dapat mempertimbangkan berbagai sudut pandang sebelum menentukan pembagian tanggung jawab.","C":"Mengusulkan penelusuran konteks sejarah melalui sumber yang kredibel, kemudian mengajak panitia membedakan peristiwa masa lalu dengan kondisi hubungan masyarakat saat ini.","D":"Menghargai pengalaman yang disampaikan, mengajak peserta menelaah konteks sejarah secara objektif, serta memastikan keputusan kepanitiaan didasarkan pada kompetensi individu tanpa menggeneralisasi kesalahan masa lalu.","E":"Mengarahkan pembahasan pada kebutuhan kegiatan, kemudian mengusulkan kriteria pemilihan penanggung jawab yang transparan agar seluruh kelompok memperoleh kesempatan berkontribusi."}},{"id":105,"section":"TKP","stem":"Anda mengikuti rapat evaluasi pelayanan administrasi kependudukan di sebuah kabupaten. Data menunjukkan bahwa satu kecamatan memiliki persentase keterlambatan pengurusan dokumen paling tinggi dibandingkan kecamatan lainnya. Seorang peserta menyimpulkan bahwa masyarakat kecamatan tersebut kurang memiliki kesadaran terhadap kewajiban administrasi. Namun, Anda mengetahui bahwa wilayah tersebut memiliki beberapa desa terpencil dengan akses transportasi dan jaringan internet terbatas. Sikap Anda adalah...","options":{"A":"Mengusulkan perbandingan data keterlambatan dengan kecamatan yang memiliki kondisi geografis serupa, kemudian menyampaikan hasilnya sebagai bahan evaluasi agar penilaian lebih proporsional.","B":"Mengajak peserta menelaah data berdasarkan akses pelayanan, kondisi infrastruktur, dan pola keterlambatan, kemudian menyusun kesimpulan berbasis bukti sebelum mengaitkannya dengan perilaku masyarakat.","C":"Menyarankan agar tim melakukan survei kepada masyarakat mengenai hambatan pengurusan dokumen, kemudian menggunakan hasilnya untuk menentukan bentuk pelayanan yang lebih sesuai.","D":"Mengajak peserta memeriksa metode penghitungan keterlambatan dan membandingkan karakteristik wilayah, kemudian meminta penanggung jawab pelayanan memberikan penjelasan tambahan.","E":"Mengusulkan peningkatan layanan administrasi keliling di wilayah dengan angka keterlambatan tinggi, kemudian mengevaluasi apakah kemudahan akses dapat memperbaiki ketepatan pengurusan dokumen."}},{"id":106,"section":"TKP","stem":"Anda tergabung dalam tim evaluasi pendidikan di sebuah daerah. Data menunjukkan bahwa siswa dari beberapa desa di wilayah pegunungan memiliki tingkat ketidakhadiran lebih tinggi dibandingkan siswa dari wilayah perkotaan. Dalam rapat, seorang peserta menyatakan bahwa kondisi tersebut membuktikan keluarga di wilayah pegunungan kurang mengutamakan pendidikan anak. Namun, laporan tersebut belum memperhitungkan jarak sekolah, kondisi jalan, keterbatasan transportasi, dan kebutuhan siswa membantu pekerjaan keluarga pada musim tertentu. Sikap Anda adalah...","options":{"A":"Mengajak tim menelaah pola ketidakhadiran berdasarkan kondisi geografis, sosial, dan ekonomi, memverifikasi penyebabnya melalui data pendukung, serta memastikan rekomendasi tidak didasarkan pada prasangka terhadap keluarga di wilayah tertentu.","B":"Mengusulkan perbandingan data kehadiran dengan wilayah lain yang memiliki karakteristik geografis serupa, kemudian menggunakan hasilnya untuk memperjelas hubungan antara akses pendidikan dan tingkat kehadiran.","C":"Meminta tim melakukan pendataan mengenai jarak rumah, kondisi transportasi, serta aktivitas keluarga siswa, kemudian menyusun rekomendasi berdasarkan hambatan yang paling sering ditemukan.","D":"Mengajak peserta mengevaluasi pola ketidakhadiran berdasarkan musim dan kondisi lingkungan, kemudian mengusulkan penyesuaian dukungan sekolah agar siswa tetap dapat mengikuti pembelajaran.","E":"Menyarankan diskusi bersama kepala sekolah dan perwakilan orang tua untuk memahami kondisi pendidikan di wilayah tersebut, kemudian menggunakan hasilnya sebagai bahan penyusunan program peningkatan kehadiran."}},{"id":107,"section":"TKP","stem":"Anda menjadi anggota tim evaluasi layanan perpustakaan daerah. Dalam rapat, seorang peserta menunjukkan bahwa tingkat keterlambatan pengembalian buku paling tinggi berasal dari pelajar yang tinggal di wilayah pinggiran kota. Ia menyimpulkan bahwa pelajar dari wilayah tersebut kurang memiliki rasa tanggung jawab terhadap fasilitas umum. Padahal, perpustakaan berada cukup jauh dari tempat tinggal mereka, layanan pengembalian hanya tersedia pada jam kerja, dan sebagian pelajar bergantung pada transportasi umum dengan jadwal terbatas. Sikap Anda adalah...","options":{"A":"Mengusulkan perbandingan tingkat keterlambatan berdasarkan jarak tempat tinggal dan ketersediaan transportasi, kemudian menyampaikan hasilnya untuk mempertimbangkan penyesuaian pelayanan.","B":"Mengajak peserta meninjau data keterlambatan berdasarkan akses transportasi, jam pelayanan, serta kondisi pengguna, kemudian membedakan hambatan pelayanan dari penilaian karakter pelajar sebelum menyusun rekomendasi.","C":"Meminta petugas perpustakaan melakukan pendataan terhadap alasan keterlambatan, kemudian menggunakan hasilnya sebagai bahan evaluasi kebijakan pengembalian buku.","D":"Mengusulkan penambahan alternatif pengembalian buku bagi pelajar wilayah pinggiran, kemudian mengevaluasi apakah kemudahan tersebut dapat menurunkan angka keterlambatan.","E":"Mengajak tim membandingkan perilaku pengembalian buku antara pelajar wilayah pinggiran dan pusat kota, kemudian meminta penanggung jawab perpustakaan menjelaskan perbedaan tingkat keterlambatan."}},{"id":108,"section":"TKP","stem":"Anda tergabung dalam tim penyusun materi pameran sejarah yang akan diselenggarakan pemerintah daerah. Salah satu panel menampilkan grafik peningkatan jumlah konflik sosial pada masa tertentu, bersamaan dengan meningkatnya jumlah penduduk pendatang. Seorang anggota tim mengusulkan keterangan bahwa kedatangan kelompok pendatang merupakan penyebab utama konflik. Padahal, laporan sejarah menunjukkan pada periode yang samajuga terjadi perubahan kebijakan pertanahan, persaingan pekerjaan, dan ketimpangan ekonomi. Materi pameran hampir selesai dicetak, sehingga perubahan harus segera diputuskan. Sikap Anda adalah...","options":{"A":"Mengusulkan agar grafik dilengkapi informasi mengenai perubahan kebijakan pertanahan dan kondisi ekonomi, kemudian meminta tim meninjau kembali keterangan yang akan ditampilkan.","B":"Mengajak tim membandingkan data kependudukan dengan catatan konflik dari beberapa sumber sejarah, kemudian menyusun keterangan yang lebih berhati-hati dalam menjelaskan hubungan keduanya.","C":"Meminta penanggung jawab materi menambahkan penjelasan tentang berbagai faktor penyebab konflik, kemudian menyesuaikan narasi agar tidak menimbulkan kesalahpahaman terhadap kelompok pendatang.","D":"Mengusulkan pemisahan grafik kependudukan dan grafik konflik dalam panel berbeda, kemudian menambahkan uraian mengenai konteks sosial pada masing-masing grafik.","E":"Mengajak tim memeriksa sumber dan metode penyusunan grafik, membedakan hubungan waktu dari bukti sebab-akibat, serta merevisi narasi berdasarkan faktor sejarah yang terverifikasi tanpa menyalahkan identitas kelompok."}},{"id":109,"section":"TKP","stem":"Anda menjadi pengelola forum diskusi daring sebuah komunitas masyarakat yang memiliki anggota dengan pandangan sosial dan politik beragam. Dalam beberapa pekan terakhir, perdebatan mengenai kebijakan pemerintah semakin tajam. Sebagian anggota mengusulkan agar seluruh pembahasan yang berpotensi menimbulkan perbedaan pendapat dilarang, sedangkan anggota lain menginginkan kebebasan menyampaikan pandangan selama tidak melanggar hukum. Kedua kelompok mulai saling menuduh tidak menghargai kebebasan dan ketertiban forum. Sikap Anda adalah...","options":{"A":"Mengajak perwakilan kedua kelompok menyusun daftar topik yang dianggap aman untuk dibahas, kemudian memberikan kesempatan kepada seluruh anggota menyampaikan masukan sebelum aturan diberlakukan.","B":"Mengusulkan sistem diskusi terjadwal dengan moderator agar setiap anggota memperoleh kesempatan berbicara secara seimbang dan pembahasan tidak didominasi kelompok tertentu.","C":"Memfasilitasi dialog mengenai kebutuhan kebebasan berpendapat dan ketertiban forum, kemudian mengusulkan mekanisme pengawasan terhadap komentar yang berpotensi menimbulkan konflik.","D":"Menyusun pedoman komunikasi yang membedakan kritik terhadap gagasan dengan serangan terhadap identitas, kemudian mengajak seluruh anggota menyepakati penerapannya secara konsisten.","E":"Mengajak anggota merumuskan tujuan forum, menyepakati aturan berdasarkan perilaku komunikasi tanpa membatasi pandangan yang sah, serta menerapkan moderasi yang transparan dan setara bagi seluruh pihak."}},{"id":110,"section":"TKP","stem":"Anda tergabung dalam tim gabungan dua organisasi masyarakat yang sedang merancang program bantuan pendidikan bagi anak-anak kurang mampu. Organisasi pertama mengusulkan agar bantuan diprioritaskan kepada keluarga yang memiliki hubungan keanggotaan dengan organisasi mereka sebagai bentuk penghargaan terhadap kontribusi anggota. Organisasi kedua menginginkan bantuan diberikan berdasarkan kondisi ekonomi tanpa membedakan latar belakang keluarga. Kedua organisasi sama-sama menyumbangkan dana dan tenaga, tetapi mulai mempertanyakan komitmen pihak lain terhadap tujuan kerja sama. Sikap Anda adalah...","options":{"A":"Mengusulkan pembagian kuota bantuan berdasarkan kontribusi masing-masing organisasi, kemudian memastikan setiap organisasi menggunakan kriteria penerima yang dapat dipertanggungjawabkan.","B":"Mengajak kedua organisasi kembali pada tujuan bantuan, membahas kepentingan masing-masing secara terbuka, serta menyepakati kriteria penerima berdasarkan kebutuhan yang terverifikasi tanpa diskriminasi identitas atau keanggotaan.","C":"Memfasilitasi penyusunan kriteria penerima bersama dengan mempertimbangkan kondisi ekonomi keluarga, kemudian memberikan kesempatan kepada kedua organisasi mengusulkan calon penerima untuk diverifikasi.","D":"Mengusulkan agar setiap organisasi menyampaikan daftar calon penerima beserta alasan prioritasnya, kemudian tim gabungan melakukan penilaian berdasarkan indikator yang disepakati bersama.","E":"Mengajak perwakilan organisasi menyusun pedoman distribusi yang transparan, kemudian menetapkan mekanisme evaluasi agar pelaksanaan bantuan dapat dipantau oleh seluruh pihak."}}];
